window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[39]={"3900":{"example:3900:exzh":"The tree's roots hold the soil in place.","example:3900:exzh2":"Plants with deep roots are sturdy.","example:3900:exzh3":"Let's look for the root of the problem.","example:3900:exzh4":"He values his family roots.","example:3900:exzh5":"Vegetables grown from the roots are delicious."},"3901":{"example:3901:exzh":"I brush my hair with a brush.","example:3901:exzh2":"This brush is very easy to use.","example:3901:exzh3":"I get a brush ready for drawing pictures.","example:3901:exzh4":"Let's go buy a brush.","example:3901:exzh5":"I brush my teeth with a brush every morning."},"3902":{"example:3902:exzh":"Tigers live in the forest.","example:3902:exzh2":"The tiger's pattern is very beautiful.","example:3902:exzh3":"You can see tigers at the zoo.","example:3902:exzh4":"The tiger is a carnivorous animal.","example:3902:exzh5":"In the movie, the tiger was the main character.","grammar:3902:ex:trans":"Tigers live in the forest.","grammar:3902:ex:structure":"トラは、森に＋住んでいます。 「トラ（虎）」 means tiger, and 「〜に住む」 means to live in …","grammar:3902:ex:explain":"The key pattern is 「〜に住んでいる」, meaning 'to live in …', with the place of residence marked by 「に」; here 「森に」 means 'in the forest'. 「住んでいます」 is the te-form of 「住む」 plus 「いる」, and since living somewhere is an ongoing state, 「ている」 is normally added. The topic 「トラ」 (tiger, usually written in katakana) is marked by 「は」, followed by a description of its habitat. The sentence states that tigers live in forests, in the tone of stating general knowledge.","grammar:3902:ex:words:0:zh":"tiger","grammar:3902:ex:words:0:note":"tiger","grammar:3902:ex:words:0:pos":"noun","grammar:3902:ex:words:1:zh":"(topic marker)","grammar:3902:ex:words:1:pos":"particle","grammar:3902:ex:words:2:zh":"forest","grammar:3902:ex:words:2:note":"もり","grammar:3902:ex:words:2:pos":"noun","grammar:3902:ex:words:3:zh":"(the place where something exists)","grammar:3902:ex:words:3:pos":"particle","grammar:3902:ex:words:4:zh":"living","grammar:3902:ex:words:4:note":"〜ている expresses a state","grammar:3902:ex:words:4:pos":"verb","grammar:3902:ex:points:1":"〜に住む：to live in … (森に = in the forest)","grammar:3902:ex2:trans":"A tiger's markings are very beautiful.","grammar:3902:ex2:structure":"〔トラの模様〕＋は、とても＋美しいです。 「模様」 means pattern, markings.","grammar:3902:ex2:words:0:zh":"tiger","grammar:3902:ex2:words:0:note":"tiger","grammar:3902:ex2:words:0:pos":"noun","grammar:3902:ex2:words:1:zh":"'s","grammar:3902:ex2:words:1:pos":"particle","grammar:3902:ex2:words:2:zh":"pattern","grammar:3902:ex2:words:2:note":"もよう","grammar:3902:ex2:words:2:pos":"noun","grammar:3902:ex2:words:3:zh":"(topic marker)","grammar:3902:ex2:words:3:pos":"particle","grammar:3902:ex2:words:4:zh":"extremely","grammar:3902:ex2:words:4:pos":"adverb","grammar:3902:ex2:words:5:zh":"beautiful","grammar:3902:ex2:words:5:note":"うつくしい","grammar:3902:ex2:words:5:pos":"adjective","grammar:3902:ex2:words:6:zh":"(polite form)","grammar:3902:ex2:words:6:pos":"copula","grammar:3902:ex2:points:0":"トラの模様：a tiger's markings","grammar:3902:ex2:points:1":"模様：pattern, markings","grammar:3902:ex3:trans":"You can see tigers at the zoo.","grammar:3902:ex3:structure":"動物園で、〔トラを見る＋ことができます〕。 「〜ことができる」 means to be able to …","grammar:3902:ex3:words:0:zh":"zoo","grammar:3902:ex3:words:0:note":"どうぶつえん","grammar:3902:ex3:words:0:pos":"noun","grammar:3902:ex3:words:1:zh":"(place of the action)","grammar:3902:ex3:words:1:pos":"particle","grammar:3902:ex3:words:2:zh":"tiger","grammar:3902:ex3:words:2:note":"tiger","grammar:3902:ex3:words:2:pos":"noun","grammar:3902:ex3:words:3:zh":"(object marker)","grammar:3902:ex3:words:3:pos":"particle","grammar:3902:ex3:words:4:zh":"look","grammar:3902:ex3:words:4:note":"dictionary form","grammar:3902:ex3:words:4:pos":"verb","grammar:3902:ex3:words:5:zh":"(nominalizer)","grammar:3902:ex3:words:5:pos":"noun","grammar:3902:ex3:words:6:zh":"(nominative)","grammar:3902:ex3:words:6:pos":"particle","grammar:3902:ex3:words:7:zh":"can","grammar:3902:ex3:words:7:note":"〜ことができる","grammar:3902:ex3:words:7:pos":"verb","grammar:3902:ex3:points:0":"動物園で：at the zoo","grammar:3902:ex3:points:1":"〜ことができる：to be able to … (見ることができる = to be able to see)","grammar:3902:ex4:trans":"Tigers are carnivorous animals.","grammar:3902:ex4:structure":"トラは、〔肉食性の動物〕＋です。","grammar:3902:ex4:words:0:zh":"tiger","grammar:3902:ex4:words:0:note":"tiger","grammar:3902:ex4:words:0:pos":"noun","grammar:3902:ex4:words:1:zh":"(topic marker)","grammar:3902:ex4:words:1:pos":"particle","grammar:3902:ex4:words:2:zh":"carnivorous","grammar:3902:ex4:words:2:note":"にくしょくせい","grammar:3902:ex4:words:2:pos":"noun","grammar:3902:ex4:words:3:zh":"'s","grammar:3902:ex4:words:3:pos":"particle","grammar:3902:ex4:words:4:zh":"animals","grammar:3902:ex4:words:4:note":"どうぶつ","grammar:3902:ex4:words:4:pos":"noun","grammar:3902:ex4:words:5:zh":"is","grammar:3902:ex4:words:5:pos":"copula","grammar:3902:ex4:points:0":"肉食性の動物：carnivorous animals","grammar:3902:ex4:points:1":"トラ：tiger","grammar:3902:ex5:trans":"The star of the movie was a tiger.","grammar:3902:ex5:structure":"映画で、トラが＋主役でした。 「主役」 means the lead role.","grammar:3902:ex5:words:0:zh":"movie","grammar:3902:ex5:words:0:note":"えいが","grammar:3902:ex5:words:0:pos":"noun","grammar:3902:ex5:words:1:zh":"(scene)","grammar:3902:ex5:words:1:pos":"particle","grammar:3902:ex5:words:2:zh":"tiger","grammar:3902:ex5:words:2:note":"tiger","grammar:3902:ex5:words:2:pos":"noun","grammar:3902:ex5:words:3:zh":"(nominative)","grammar:3902:ex5:words:3:pos":"particle","grammar:3902:ex5:words:4:zh":"lead role","grammar:3902:ex5:words:4:note":"しゅやく","grammar:3902:ex5:words:4:pos":"noun","grammar:3902:ex5:words:5:zh":"(past) was","grammar:3902:ex5:words:5:pos":"copula","grammar:3902:ex5:points:0":"映画で：in the movie","grammar:3902:ex5:points:1":"主役：the lead role"},"3903":{"example:3903:exzh":"That child is pitiful, isn't he?","example:3903:exzh2":"I want to help animals in distress.","example:3903:exzh3":"After hearing her story, I felt sorry for her.","example:3903:exzh4":"I help him, who has been placed in a pitiful situation.","example:3903:exzh5":"That movie made people feel very sorry."},"3904":{"example:3904:exzh":"I have been abroad.","example:3904:exzh2":"I want to learn about cultures abroad.","example:3904:exzh3":"He works abroad.","example:3904:exzh4":"Going to a foreign country is fun.","example:3904:exzh5":"Recently, a friend from abroad came to visit."},"3905":{"example:3905:exzh":"He is always complaining.","example:3905:exzh2":"If we receive a complaint, we respond right away.","example:3905:exzh3":"You can submit a complaint in writing.","example:3905:exzh4":"If there are many complaints, the reputation goes down.","example:3905:exzh5":"She resolved the complaint."},"3906":{"example:3906:exzh":"Where do you want to go?","example:3906:exzh2":"Thanks to you, I was helped.","example:3906:exzh3":"Please tell me your opinion.","example:3906:exzh4":"You say funny things, don't you?","example:3906:exzh5":"I want to go together with you."},"3907":{"example:3907:exzh":"My ancestors lived in Japan.","example:3907:exzh2":"It is important to respect one's ancestors.","example:3907:exzh3":"I want to learn about my ancestors' history.","example:3907:exzh4":"I visited my ancestors' graves.","example:3907:exzh5":"This is the surname inherited from my ancestors."},"3908":{"example:3908:exzh":"He suffered a physical injury.","example:3908:exzh2":"Treating an external injury takes time.","example:3908:exzh3":"If there is an injury, let's go to the hospital.","example:3908:exzh4":"The symptoms of the injury improved.","example:3908:exzh5":"When the injury hurts, rest is necessary."},"3909":{"example:3909:exzh":"I like rooms with high ceilings.","example:3909:exzh2":"I changed the color of the ceiling.","example:3909:exzh3":"There is a hole in the ceiling.","example:3909:exzh4":"This room has a low ceiling.","example:3909:exzh5":"A bug fell from the ceiling."},"3910":{"example:3910:exzh":"Please send the package.","example:3910:exzh2":"A friend sent me a letter.","example:3910:exzh3":"I had him send me the information.","example:3910:exzh4":"Please send the materials over soon.","example:3910:exzh5":"They sent me the email that came from my mother."},"3911":{"example:3911:exzh":"I use Kirk to save data.","example:3911:exzh2":"Kirk is safe.","example:3911:exzh3":"I keep backups on Kirk.","example:3911:exzh4":"More and more people are using Kirk.","example:3911:exzh5":"I checked Kirk's storage capacity."},"3912":{"example:3912:exzh":"He has great ambition.","example:3912:exzh2":"People with ambition tend to succeed easily.","example:3912:exzh3":"I'm pursuing my own ambition.","example:3912:exzh4":"Without ambition, you can't move forward.","example:3912:exzh5":"Her ambition is very strong."},"3913":{"example:3913:exzh":"I saw a hippo at the zoo.","example:3913:exzh2":"Hippos like being in the water.","example:3913:exzh3":"A hippo is a large animal.","example:3913:exzh4":"Hippos are herbivores.","example:3913:exzh5":"Hippos live in Africa."},"3914":{"example:3914:exzh":"His grades are going down.","example:3914:exzh2":"The economic decline is a cause for concern.","example:3914:exzh3":"We need to analyze the cause of the decline.","example:3914:exzh4":"There are reports that the alert level has been lowered.","example:3914:exzh5":"I can feel my health declining."},"3915":{"example:3915:exzh":"Flowers are blooming on the outside.","example:3915:exzh2":"Please look at the outside of that building.","example:3915:exzh3":"The outer part is especially important.","example:3915:exzh4":"I cleaned the outside until it was spotless.","example:3915:exzh5":"It's very windy outside."},"3916":{"example:3916:exzh":"There's a gathering of friends tomorrow.","example:3916:exzh2":"A gathering is a place for fun conversation.","example:3916:exzh3":"We decided on a place for everyone to get together.","example:3916:exzh4":"I want to join the gathering.","example:3916:exzh5":"The gatherings are always fun."},"3917":{"example:3917:exzh":"The economic outlook is bright.","example:3917:exzh2":"I drew up an outlook for next year.","example:3917:exzh3":"It's important to consider the outlook.","example:3917:exzh4":"If your forecast is too optimistic, problems will come up.","example:3917:exzh5":"Let's talk about the outlook for that situation."},"3918":{"example:3918:exzh":"The dog bared its fangs and growled.","example:3918:exzh2":"Dogs have sharp fangs.","example:3918:exzh3":"Lions catch their prey with sharp fangs.","example:3918:exzh4":"An elephant's tusks are called ivory.","example:3918:exzh5":"A venomous snake's fangs contain venom."},"3919":{"example:3919:exzh":"This piece of craftwork is very beautiful.","example:3919:exzh2":"He's good at handicrafts.","example:3919:exzh3":"You need tools to do the craftwork.","example:3919:exzh4":"I want to learn craftwork techniques.","example:3919:exzh5":"This piece of craftwork took a lot of time."},"3920":{"example:3920:exzh":"This room faces south.","example:3920:exzh2":"Different orientations change how things look.","example:3920:exzh3":"He changed his own direction.","example:3920:exzh4":"The wind direction changed.","example:3920:exzh5":"I work in a good direction."},"3921":{"example:3921:exzh":"That dress suits you.","example:3921:exzh2":"She looks good in floral patterns.","example:3921:exzh3":"Let's choose a color that suits you.","example:3921:exzh4":"This hairstyle doesn't suit you.","example:3921:exzh5":"He looks great in a suit."},"3922":{"example:3922:exzh":"Take off this necklace.","example:3922:exzh2":"May I take off my glasses?","example:3922:exzh3":"You have to take off your ring before surgery.","example:3922:exzh4":"He took off his hat.","example:3922:exzh5":"Please remove this part."},"3923":{"example:3923:exzh":"I go jogging every morning.","example:3923:exzh2":"He drinks coffee every morning.","example:3923:exzh3":"I read the newspaper every morning.","example:3923:exzh4":"I go to school every morning.","example:3923:exzh5":"Getting up early every morning is tough.","grammar:3923:ex:trans":"I go jogging every morning.","grammar:3923:ex:structure":"time, noun＋を＋します. 「毎朝」 expresses habitual frequency.","grammar:3923:ex:explain":"The key point is the time noun 「毎朝」 (every morning) used adverbially to express habit and frequency. 「ジョギングをする」 is formed as 「noun＋をする」, \"to jog,\" with the object taking 「を」. 「します」 is the masu-form and here expresses a repeated, habitual action (running every day), not a single future event. The sentence describes the daily habit of jogging every morning and is a typical habit sentence built from a frequency word plus an action noun plus をする.","grammar:3923:ex:words:0:zh":"every morning","grammar:3923:ex:words:0:note":"まいあさ","grammar:3923:ex:words:0:pos":"noun","grammar:3923:ex:words:1:zh":"jogging","grammar:3923:ex:words:1:note":"loanword: jogging","grammar:3923:ex:words:1:pos":"noun","grammar:3923:ex:words:2:zh":"(object marker)","grammar:3923:ex:words:2:pos":"particle","grammar:3923:ex:words:3:zh":"do","grammar:3923:ex:words:3:note":"ジョギングをする＝ to jog","grammar:3923:ex:words:3:pos":"verb","grammar:3923:ex:points:0":"毎朝: every morning","grammar:3923:ex:points:1":"ジョギングをする: to jog","grammar:3923:ex2:trans":"He drinks coffee every morning.","grammar:3923:ex2:structure":"〜は＋毎朝＋noun＋を＋飲みます.","grammar:3923:ex2:words:0:zh":"he","grammar:3923:ex2:words:0:note":"かれ","grammar:3923:ex2:words:0:pos":"pronoun","grammar:3923:ex2:words:1:zh":"(topic marker)","grammar:3923:ex2:words:1:pos":"particle","grammar:3923:ex2:words:2:zh":"every morning","grammar:3923:ex2:words:2:note":"まいあさ","grammar:3923:ex2:words:2:pos":"noun","grammar:3923:ex2:words:3:zh":"coffee","grammar:3923:ex2:words:3:note":"loanword","grammar:3923:ex2:words:3:pos":"noun","grammar:3923:ex2:words:4:zh":"(object marker)","grammar:3923:ex2:words:4:pos":"particle","grammar:3923:ex2:words:5:zh":"to drink","grammar:3923:ex2:words:5:note":"のみます","grammar:3923:ex2:words:5:pos":"verb","grammar:3923:ex2:points:0":"毎朝: every morning","grammar:3923:ex2:points:1":"コーヒーを飲む: to drink coffee","grammar:3923:ex3:trans":"I read the newspaper every morning.","grammar:3923:ex3:structure":"time, noun＋を＋読む.","grammar:3923:ex3:words:0:zh":"every morning","grammar:3923:ex3:words:0:note":"まいあさ","grammar:3923:ex3:words:0:pos":"noun","grammar:3923:ex3:words:1:zh":"newspaper","grammar:3923:ex3:words:1:note":"しんぶん","grammar:3923:ex3:words:1:pos":"noun","grammar:3923:ex3:words:2:zh":"(object marker)","grammar:3923:ex3:words:2:pos":"particle","grammar:3923:ex3:words:3:zh":"read","grammar:3923:ex3:words:3:note":"よむ","grammar:3923:ex3:words:3:pos":"verb","grammar:3923:ex3:points:0":"毎朝: every morning","grammar:3923:ex3:points:1":"新聞を読む: to read the newspaper","grammar:3923:ex4:trans":"I go to school every morning.","grammar:3923:ex4:structure":"place＋に＋毎朝＋通っている. 「〜に通う」＝ to commute to / attend (school).","grammar:3923:ex4:words:0:zh":"school","grammar:3923:ex4:words:0:note":"がっこう","grammar:3923:ex4:words:0:pos":"noun","grammar:3923:ex4:words:1:zh":"(the destination)","grammar:3923:ex4:words:1:pos":"particle","grammar:3923:ex4:words:2:zh":"every morning","grammar:3923:ex4:words:2:note":"まいあさ","grammar:3923:ex4:words:2:pos":"noun","grammar:3923:ex4:words:3:zh":"commuting to work / attending school","grammar:3923:ex4:words:3:note":"〜ている expresses a habitual state","grammar:3923:ex4:words:3:pos":"verb","grammar:3923:ex4:points:0":"〜に通う: to go to… regularly, to attend (school / work)","grammar:3923:ex4:points:1":"毎朝: every morning","grammar:3923:ex5:trans":"Getting up early every morning is hard.","grammar:3923:ex5:structure":"〔毎朝早起きする＋の〕＋は＋na-adjective＋です.","grammar:3923:ex5:words:0:zh":"every morning","grammar:3923:ex5:words:0:note":"まいあさ","grammar:3923:ex5:words:0:pos":"noun","grammar:3923:ex5:words:1:zh":"getting up early","grammar:3923:ex5:words:1:note":"はやおきする; dictionary form","grammar:3923:ex5:words:1:pos":"verb","grammar:3923:ex5:words:2:zh":"(nominalizer)","grammar:3923:ex5:words:2:pos":"particle","grammar:3923:ex5:words:3:zh":"(topic marker)","grammar:3923:ex5:words:3:pos":"particle","grammar:3923:ex5:words:4:zh":"tough","grammar:3923:ex5:words:4:note":"たいへん","grammar:3923:ex5:words:4:pos":"na-adjective","grammar:3923:ex5:words:5:zh":"(polite form)","grammar:3923:ex5:words:5:pos":"copula","grammar:3923:ex5:points:0":"verb＋の＋は: doing … (the act itself)","grammar:3923:ex5:points:1":"早起きする: to get up early","exam:3923:zh":"I get up at six every morning and run before breakfast, without missing a single day.","exam:3923:why":"「毎朝」 means every morning, which fits getting up and running before breakfast each day. 「毎週」 means every week, which doesn't match 「一日も休まず」."},"3924":{"example:3924:exzh":"Israel is located in the Middle East.","example:3924:exzh2":"Israeli food is very delicious.","example:3924:exzh3":"He's interested in Israeli culture.","example:3924:exzh4":"Israel has beautiful nature.","example:3924:exzh5":"Israel's history is very complex."},"3925":{"example:3925:exzh":"I like steak.","example:3925:exzh2":"This restaurant's steak is delicious.","example:3925:exzh3":"Please cook the steak medium.","example:3925:exzh4":"He ate a lot of steak.","example:3925:exzh5":"The steak comes with a salad."},"3926":{"example:3926:exzh":"Please come in through the back door.","example:3926:exzh2":"That building has a back door.","example:3926:exzh3":"There aren't many people at the back door.","example:3926:exzh4":"The back door is very quiet.","example:3926:exzh5":"He's waiting at the back door."},"3927":{"example:3927:exzh":"This park is divided into sections.","example:3927:exzh2":"Please specify the size of the section.","example:3927:exzh3":"He works on plot division.","example:3927:exzh4":"The town is being reorganized into plots.","example:3927:exzh5":"We need to divide the farmland into plots."},"3928":{"example:3928:exzh":"He was shot dead.","example:3928:exzh2":"The shooting made the news.","example:3928:exzh3":"The police shot the culprit dead.","example:3928:exzh4":"The reason for the shooting is still unknown.","example:3928:exzh5":"This incident is connected to the shooting."},"3929":{"example:3929:exzh":"Chicken is very tasty.","example:3929:exzh2":"This chicken is fresh.","example:3929:exzh3":"The chicken is crowing.","example:3929:exzh4":"We keep chickens at my house.","example:3929:exzh5":"Chicken eggs are full of nutrition."},"3930":{"example:3930:exzh":"I like drinking Scotch with friends.","example:3930:exzh2":"Scotch is a warm drink.","example:3930:exzh3":"This Scotch is especially good.","example:3930:exzh4":"There's a whisky party this weekend.","example:3930:exzh5":"When we drink Scotch, we use a half glass."},"3931":{"example:3931:exzh":"I carried the meal on a tray.","example:3931:exzh2":"I borrowed a tray at the café.","example:3931:exzh3":"Trays are easy to wash.","example:3931:exzh4":"I arranged the sweets on a tray.","example:3931:exzh5":"I bought a new tray."},"3933":{"example:3933:exzh":"I'm meeting a friend on Saturday.","example:3933:exzh2":"This Saturday is busy.","example:3933:exzh3":"I'm going to see a movie on Saturday.","example:3933:exzh4":"Saturday is a day for relaxing.","example:3933:exzh5":"On Saturday I'll get a nice long sleep.","grammar:3933:ex:trans":"I'm meeting a friend on Saturday.","grammar:3933:ex:structure":"〜に〜と会います","grammar:3933:ex:explain":"There are two key points. First, the time particle 「に」: a specific point in time such as a day of the week takes 「に」, so 「土曜日に」 means on Saturday. Second, 「〜と会う」: the person you meet takes 「と」 (marking a joint action), so 「友達と会う」 means to meet a friend. 「会います」 is the masu-form (polite form). The sentence says you're meeting a friend on Saturday, and the pairing of 「に」 for the time and 「と」 for the person is the main point.","grammar:3933:ex:words:0:zh":"Saturday","grammar:3933:ex:words:0:note":"どようび","grammar:3933:ex:words:0:pos":"noun","grammar:3933:ex:words:1:zh":"(point in time)","grammar:3933:ex:words:1:pos":"particle","grammar:3933:ex:words:2:zh":"friend","grammar:3933:ex:words:2:note":"ともだち","grammar:3933:ex:words:2:pos":"noun","grammar:3933:ex:words:3:zh":"(object)","grammar:3933:ex:words:3:pos":"particle","grammar:3933:ex:words:4:zh":"meet","grammar:3933:ex:words:4:note":"あいます","grammar:3933:ex:words:4:pos":"verb","grammar:3933:ex:points:0":"❗土曜日 (どようび): Saturday; 〜に会う = to meet (a person).","grammar:3933:ex:points:1":"土曜日に: on Saturday.","grammar:3933:ex2:trans":"This Saturday is busy.","grammar:3933:ex2:structure":"〜の土曜日は忙しいです","grammar:3933:ex2:words:0:zh":"this week","grammar:3933:ex2:words:0:note":"こんしゅう","grammar:3933:ex2:words:0:pos":"noun","grammar:3933:ex2:words:1:zh":"'s","grammar:3933:ex2:words:1:pos":"particle","grammar:3933:ex2:words:2:zh":"Saturday","grammar:3933:ex2:words:2:note":"どようび","grammar:3933:ex2:words:2:pos":"noun","grammar:3933:ex2:words:3:zh":"(topic)","grammar:3933:ex2:words:3:pos":"particle","grammar:3933:ex2:words:4:zh":"busy","grammar:3933:ex2:words:4:note":"いそがしい","grammar:3933:ex2:words:4:pos":"adjective","grammar:3933:ex2:words:5:zh":"(polite form)","grammar:3933:ex2:words:5:pos":"copula","grammar:3933:ex2:points:0":"❗今週の土曜日: this Saturday; 忙しい = busy.","grammar:3933:ex2:points:1":"今週の土曜日: this Saturday.","grammar:3933:ex3:trans":"I'm going to see a movie on Saturday.","grammar:3933:ex3:structure":"〜に〜を観に行きます","grammar:3933:ex3:words:0:zh":"Saturday","grammar:3933:ex3:words:0:note":"どようび","grammar:3933:ex3:words:0:pos":"noun","grammar:3933:ex3:words:1:zh":"(point in time)","grammar:3933:ex3:words:1:pos":"particle","grammar:3933:ex3:words:2:zh":"movie","grammar:3933:ex3:words:2:note":"えいが","grammar:3933:ex3:words:2:pos":"noun","grammar:3933:ex3:words:3:zh":"(object marker)","grammar:3933:ex3:words:3:pos":"particle","grammar:3933:ex3:words:4:zh":"look","grammar:3933:ex3:words:4:note":"み","grammar:3933:ex3:words:4:pos":"noun","grammar:3933:ex3:words:5:zh":"(purpose)","grammar:3933:ex3:words:5:pos":"particle","grammar:3933:ex3:words:6:zh":"go","grammar:3933:ex3:words:6:pos":"verb","grammar:3933:ex3:points:0":"❗〜を観に行く: to go see… (watch a film or show); 映画を観る = to watch a movie.","grammar:3933:ex3:points:1":"映画を観に行く: to go see a movie.","grammar:3933:ex4:trans":"Saturday is a day to relax.","grammar:3933:ex4:structure":"〜はリラックスする日です","grammar:3933:ex4:words:0:zh":"Saturday","grammar:3933:ex4:words:0:note":"どようび","grammar:3933:ex4:words:0:pos":"noun","grammar:3933:ex4:words:1:zh":"(topic)","grammar:3933:ex4:words:1:pos":"particle","grammar:3933:ex4:words:2:zh":"relax","grammar:3933:ex4:words:2:pos":"verb","grammar:3933:ex4:words:3:zh":"day","grammar:3933:ex4:words:3:note":"ひ","grammar:3933:ex4:words:3:pos":"noun","grammar:3933:ex4:words:4:zh":"is","grammar:3933:ex4:words:4:pos":"copula","grammar:3933:ex4:points:0":"❗リラックスする: to relax (relax); リラックスする日 = a relaxing day.","grammar:3933:ex4:points:1":"リラックス: relaxation.","grammar:3933:ex5:trans":"On Saturday I take my time and sleep well.","grammar:3933:ex5:structure":"土曜日にはゆっくり眠ります","grammar:3933:ex5:words:0:zh":"Saturday","grammar:3933:ex5:words:0:note":"どようび","grammar:3933:ex5:words:0:pos":"noun","grammar:3933:ex5:words:1:zh":"(point in time)","grammar:3933:ex5:words:1:pos":"particle","grammar:3933:ex5:words:2:zh":"(contrast)","grammar:3933:ex5:words:2:pos":"particle","grammar:3933:ex5:words:3:zh":"well","grammar:3933:ex5:words:3:pos":"adverb","grammar:3933:ex5:words:4:zh":"sleep","grammar:3933:ex5:words:4:note":"ねむります","grammar:3933:ex5:words:4:pos":"verb","grammar:3933:ex5:points:0":"❗ゆっくり眠る: to get a good sleep (ゆっくり = at one's leisure).","grammar:3933:ex5:points:1":"ゆっくり眠る: to sleep well.","exam:3933:zh":"The day after Friday is Saturday.","exam:3933:why":"「土曜日」 is Saturday, which comes after Friday. 「日曜日」 is Sunday, one day later than Saturday."},"3934":{"example:3934:exzh":"This cloth is three yards long.","example:3934:exzh2":"One yard is three feet.","example:3934:exzh3":"I use a tape measure to measure yards.","example:3934:exzh4":"He's good at calculating yards.","example:3934:exzh5":"I used yards to decide the scale of the garden."},"3935":{"example:3935:exzh":"He practices every day for the competition.","example:3935:exzh2":"Teamwork is important in competitions.","example:3935:exzh3":"We're going to take part in the competition.","example:3935:exzh4":"Let's make sure we understand the competition rules well.","example:3935:exzh5":"Many people like competition."},"3936":{"example:3936:exzh":"He has a peaceful look on his face.","example:3936:exzh2":"It's important to sleep peacefully.","example:3936:exzh3":"She was sitting peacefully.","example:3936:exzh4":"It's important to live with a peaceful heart.","example:3936:exzh5":"This place is truly peaceful."},"3938":{"example:3938:exzh":"He is carrying a big load on his back.","example:3938:exzh2":"I take a walk with the child on my back.","example:3938:exzh3":"It's hard to carry this bag on your back.","example:3938:exzh4":"It's important to carry tradition on your shoulders.","example:3938:exzh5":"I'll move around while carrying the heavy luggage on my back."},"3939":{"example:3939:exzh":"The cat drove away the birds in the garden.","example:3939:exzh2":"That dog drove off the bad person.","example:3939:exzh3":"I don't intend to drive him away.","example:3939:exzh4":"Her scream drove away all the animals.","example:3939:exzh5":"The wind is blowing to drive away the fog."},"3940":{"example:3940:exzh":"Wow, amazing!","example:3940:exzh2":"Wow, look!","example:3940:exzh3":"Wow, how beautiful!","example:3940:exzh4":"Wow, really?","example:3940:exzh5":"Wow, this is fun!","grammar:3940:ex:trans":"Wow, amazing!","grammar:3940:ex:structure":"わあ、すごい！ 「わあ」 is an exclamation of wonder.","grammar:3940:ex:explain":"The key point is the interjection 「わあ」, used to express surprise, admiration, or excitement — the equivalent of English wow — placed at the start of the sentence on its own, carrying strong emotion. 「すごい」 is an i-adjective whose basic meaning is amazing, incredible, and in casual speech it's often used alone as an exclamation meaning awesome, amazing. The whole sentence is an admiring outburst when you see something impressive; the tone is lively and casual, a typical way to express an immediate feeling in everyday conversation.","grammar:3940:ex:words:0:zh":"wow","grammar:3940:ex:words:0:note":"surprise / admiration","grammar:3940:ex:words:0:pos":"interjection","grammar:3940:ex:words:1:zh":"amazing / awesome","grammar:3940:ex:words:1:pos":"adjective","grammar:3940:ex:points:0":"わあ: wow (surprise, admiration)","grammar:3940:ex:points:1":"すごい: amazing, awesome","grammar:3940:ex2:trans":"Wow, look!","grammar:3940:ex2:structure":"わあ、見て！ 「見て」 is the te-form used as a casual command: look!","grammar:3940:ex2:words:0:zh":"wow","grammar:3940:ex2:words:0:note":"admiration","grammar:3940:ex2:words:0:pos":"interjection","grammar:3940:ex2:words:1:zh":"look","grammar:3940:ex2:words:1:note":"みて; te-form (casual command)","grammar:3940:ex2:words:1:pos":"verb","grammar:3940:ex2:points:0":"〜て (casual command): do …! (見て = look!)","grammar:3940:ex2:points:1":"わあ: wow","grammar:3940:ex3:trans":"Wow, how beautiful!","grammar:3940:ex3:structure":"わあ、なんて＋i-adjective！ なんて〜 = how … (exclamation).","grammar:3940:ex3:words:0:zh":"wow","grammar:3940:ex3:words:0:note":"admiration","grammar:3940:ex3:words:0:pos":"interjection","grammar:3940:ex3:words:1:zh":"how much","grammar:3940:ex3:words:1:note":"exclamatory usage","grammar:3940:ex3:words:1:pos":"adverb","grammar:3940:ex3:words:2:zh":"beautiful","grammar:3940:ex3:words:2:note":"うつくしい","grammar:3940:ex3:words:2:pos":"adjective","grammar:3940:ex3:points:0":"なんて〜: how … (exclamatory pattern)","grammar:3940:ex3:points:1":"美しい: beautiful","grammar:3940:ex4:trans":"Wow, really?","grammar:3940:ex4:structure":"わあ、本当に？ 本当に？ = really? (a surprised echo question).","grammar:3940:ex4:words:0:zh":"wow","grammar:3940:ex4:words:0:note":"surprised","grammar:3940:ex4:words:0:pos":"interjection","grammar:3940:ex4:words:1:zh":"really","grammar:3940:ex4:words:1:note":"ほんとうに","grammar:3940:ex4:words:1:pos":"adverb","grammar:3940:ex4:points:0":"本当に？: really? (surprised echo question)","grammar:3940:ex4:points:1":"わあ: wow","grammar:3940:ex5:trans":"Wow, so fun!","grammar:3940:ex5:structure":"わあ、楽しい！","grammar:3940:ex5:words:0:zh":"wow","grammar:3940:ex5:words:0:note":"joy","grammar:3940:ex5:words:0:pos":"interjection","grammar:3940:ex5:words:1:zh":"happy, fun","grammar:3940:ex5:words:1:note":"たのしい","grammar:3940:ex5:words:1:pos":"adjective","grammar:3940:ex5:points:0":"楽しい: fun, enjoyable","grammar:3940:ex5:points:1":"わあ: wow (exclamation of joy)"},"3941":{"example:3941:exzh":"It's not my turn yet.","example:3941:exzh2":"Please follow the order.","example:3941:exzh3":"Next is your turn.","example:3941:exzh4":"Please wait until your turn comes.","example:3941:exzh5":"Everyone is lining up in order.","grammar:3941:ex:trans":"It's not my turn yet.","grammar:3941:ex:structure":"〔私の順番〕＋は、まだです. 「順番」 = order, turn; 「まだです」 = not yet.","grammar:3941:ex:explain":"The key point is 「まだです」, meaning “not yet”; 「まだ」 is the adverb “still / yet,” and adding 「です」 makes it polite and implies that something hasn't happened yet. 「順番」 means order or turn. 「私の順番」 links with 「の」 to give “my turn,” marked as the topic with 「は」. The sentence means “It's not my turn yet”; this shortened way of saying “not yet” with adverb ＋ です is very natural in casual speech.","grammar:3941:ex:words:0:zh":"I","grammar:3941:ex:words:0:note":"わたし","grammar:3941:ex:words:0:pos":"pronoun","grammar:3941:ex:words:1:zh":"'s","grammar:3941:ex:words:1:pos":"particle","grammar:3941:ex:words:2:zh":"order","grammar:3941:ex:words:2:note":"じゅんばん","grammar:3941:ex:words:2:pos":"noun","grammar:3941:ex:words:3:zh":"(topic marker)","grammar:3941:ex:words:3:pos":"particle","grammar:3941:ex:words:4:zh":"not yet","grammar:3941:ex:words:4:pos":"adverb","grammar:3941:ex:words:5:zh":"(polite form)","grammar:3941:ex:words:5:pos":"copula","grammar:3941:ex:points:0":"順番（じゅんばん）: order, turn","grammar:3941:ex:points:1":"まだです: not yet (one's turn)","grammar:3941:ex2:trans":"Please follow the order.","grammar:3941:ex2:structure":"順番を＋守ってください. 「順番を守る」 = to follow the order.","grammar:3941:ex2:words:0:zh":"order","grammar:3941:ex2:words:0:note":"じゅんばん","grammar:3941:ex2:words:0:pos":"noun","grammar:3941:ex2:words:1:zh":"(object marker)","grammar:3941:ex2:words:1:pos":"particle","grammar:3941:ex2:words:2:zh":"obey","grammar:3941:ex2:words:2:note":"te-form","grammar:3941:ex2:words:2:pos":"verb","grammar:3941:ex2:words:3:zh":"please","grammar:3941:ex2:words:3:note":"〜てください","grammar:3941:ex2:words:3:pos":"verb","grammar:3941:ex2:points:0":"順番を守る: to follow the order","grammar:3941:ex2:points:1":"守ってください: please follow","grammar:3941:ex3:trans":"Next is your turn.","grammar:3941:ex3:structure":"次は、〔あなたの順番〕＋です. 「次は」 = next.","grammar:3941:ex3:words:0:zh":"from now on","grammar:3941:ex3:words:0:note":"つぎ","grammar:3941:ex3:words:0:pos":"noun","grammar:3941:ex3:words:1:zh":"(topic marker)","grammar:3941:ex3:words:1:pos":"particle","grammar:3941:ex3:words:2:zh":"you","grammar:3941:ex3:words:2:pos":"pronoun","grammar:3941:ex3:words:3:zh":"'s","grammar:3941:ex3:words:3:pos":"particle","grammar:3941:ex3:words:4:zh":"order","grammar:3941:ex3:words:4:note":"じゅんばん","grammar:3941:ex3:words:4:pos":"noun","grammar:3941:ex3:words:5:zh":"is","grammar:3941:ex3:words:5:pos":"copula","grammar:3941:ex3:points:0":"次はあなたの順番: now it's your turn","grammar:3941:ex3:points:1":"順番: order, turn","grammar:3941:ex4:trans":"Please wait until your turn comes.","grammar:3941:ex4:structure":"〔順番が来る＋まで〕、待ってください. 「〜まで」 = until…; 「順番が来る」 = one's turn comes.","grammar:3941:ex4:words:0:zh":"order","grammar:3941:ex4:words:0:note":"じゅんばん","grammar:3941:ex4:words:0:pos":"noun","grammar:3941:ex4:words:1:zh":"(nominative)","grammar:3941:ex4:words:1:pos":"particle","grammar:3941:ex4:words:2:zh":"(the time) came","grammar:3941:ex4:words:2:note":"くる; dictionary form","grammar:3941:ex4:words:2:pos":"verb","grammar:3941:ex4:words:3:zh":"until","grammar:3941:ex4:words:3:note":"limit","grammar:3941:ex4:words:3:pos":"particle","grammar:3941:ex4:words:4:zh":"wait","grammar:3941:ex4:words:4:note":"te-form","grammar:3941:ex4:words:4:pos":"verb","grammar:3941:ex4:words:5:zh":"please","grammar:3941:ex4:words:5:note":"〜てください","grammar:3941:ex4:words:5:pos":"verb","grammar:3941:ex4:points:0":"順番が来る: one's turn comes","grammar:3941:ex4:points:1":"〜まで待つ: to wait until…","grammar:3941:ex5:trans":"Everyone is lined up in order.","grammar:3941:ex5:structure":"みんなは、〔順番通りに〕、並んでいます. 「〜通りに」 = according to…, following…","grammar:3941:ex5:words:0:zh":"everyone","grammar:3941:ex5:words:0:pos":"noun","grammar:3941:ex5:words:1:zh":"(topic marker)","grammar:3941:ex5:words:1:pos":"particle","grammar:3941:ex5:words:2:zh":"order","grammar:3941:ex5:words:2:note":"じゅんばん","grammar:3941:ex5:words:2:pos":"noun","grammar:3941:ex5:words:3:zh":"according to","grammar:3941:ex5:words:3:note":"どおり","grammar:3941:ex5:words:3:pos":"noun","grammar:3941:ex5:words:4:zh":"(a state)","grammar:3941:ex5:words:4:pos":"particle","grammar:3941:ex5:words:5:zh":"lining up","grammar:3941:ex5:words:5:note":"〜ている expresses a state","grammar:3941:ex5:words:5:pos":"verb","grammar:3941:ex5:points:0":"順番通りに: in order","grammar:3941:ex5:points:1":"〜通りに: according to… (順番通り = in order)"},"3942":{"example:3942:exzh":"What time is it now?","example:3942:exzh2":"A special moment has come.","example:3942:exzh3":"Please don't forget this moment.","example:3942:exzh4":"He is someone who values time.","example:3942:exzh5":"He was there at that moment."},"3943":{"example:3943:exzh":"This bay is beautiful.","example:3943:exzh2":"A boat is moored in the bay.","example:3943:exzh3":"That bay is a tourist spot.","example:3943:exzh4":"The water in the bay is clear.","example:3943:exzh5":"I like fishing in the bay."},"3945":{"example:3945:exzh":"The tip of this pen broke.","example:3945:exzh2":"It's a company that uses cutting-edge technology.","example:3945:exzh3":"I stare at the tip.","example:3945:exzh4":"He is wearing cutting-edge fashion.","example:3945:exzh5":"If the tip is thin, you can write precisely."},"3946":{"example:3946:exzh":"Houston is a big city.","example:3946:exzh2":"Have you ever been to Houston?","example:3946:exzh3":"He lives in Houston.","example:3946:exzh4":"How's the weather in Houston?","example:3946:exzh5":"I ate delicious food in Houston."},"3947":{"example:3947:exzh":"Griffin is an interesting character.","example:3947:exzh2":"He voices Griffin.","example:3947:exzh3":"Griffin's story is popular.","example:3947:exzh4":"We'll talk about Griffin.","example:3947:exzh5":"Have you seen the Griffin movie?"},"3948":{"example:3948:exzh":"The ball is rolling.","example:3948:exzh2":"Kids like rolling around.","example:3948:exzh3":"The leaves are rolling.","example:3948:exzh4":"The car rolls down the slope.","example:3948:exzh5":"The stone rolled into the river."},"3949":{"example:3949:exzh":"There was a lot of criticism of his opinion.","example:3949:exzh2":"This movie is receiving criticism.","example:3949:exzh3":"Criticism is sometimes necessary.","example:3949:exzh4":"Let's speak our minds without fearing criticism.","example:3949:exzh5":"Criticism of society is growing."},"3951":{"example:3951:exzh":"I'm looking forward to visiting tourist spots.","example:3951:exzh2":"This town has a lot of tourists.","example:3951:exzh3":"We plan to visit famous tourist sites.","example:3951:exzh4":"We'll tour the city by sightseeing bus.","example:3951:exzh5":"A sightseeing guide showed us around."},"3952":{"example:3952:exzh":"I received an apology from him.","example:3952:exzh2":"An apology is necessary.","example:3952:exzh3":"She offered an apology.","example:3952:exzh4":"I wrote a letter of apology.","example:3952:exzh5":"Please apologize again and again."},"3953":{"example:3953:exzh":"Bad behavior is not tolerated.","example:3953:exzh2":"We're investigating the cause of the defect.","example:3953:exzh3":"A defect in the product was reported.","example:3953:exzh4":"The defective condition continues.","example:3953:exzh5":"We need measures against bad behavior."},"3954":{"example:3954:exzh":"The securities market is becoming active.","example:3954:exzh2":"I bought some securities.","example:3954:exzh3":"I work at a securities company.","example:3954:exzh4":"Securities are part of investing.","example:3954:exzh5":"Securities trading is increasing."},"3955":{"example:3955:exzh":"I can relate to what he's thinking.","example:3955:exzh2":"We need to come up with new ideas.","example:3955:exzh3":"You should think flexibly.","example:3955:exzh4":"I went and asked what he's thinking.","example:3955:exzh5":"Let's share what we're thinking.","grammar:3955:ex:trans":"I can relate to what he's thinking.","grammar:3955:ex:structure":"〜の考えていることには共感できます","grammar:3955:ex:explain":"「彼の考えていること」 is equivalent to 「彼が考えていること」; here 「の」 marks the subject of the modifying clause rather than simply showing possession. 「こと」 refers to the thing he is thinking. In 「には」, 「に」 first marks the target of one's empathy, then 「は」 brings it up as the topic or for contrast. 「共感できます」 means being able to understand and feel sympathy — it doesn't necessarily mean agreeing on every point.","grammar:3955:ex:words:0:zh":"he","grammar:3955:ex:words:0:note":"かれ","grammar:3955:ex:words:0:pos":"pronoun","grammar:3955:ex:words:1:zh":"(subject in a modifying clause)","grammar:3955:ex:words:1:pos":"particle","grammar:3955:ex:words:2:zh":"think","grammar:3955:ex:words:2:note":"かんがえ","grammar:3955:ex:words:2:pos":"verb","grammar:3955:ex:words:3:zh":"(connects to an auxiliary verb)","grammar:3955:ex:words:3:pos":"particle","grammar:3955:ex:words:4:zh":"(an ongoing thought or idea)","grammar:3955:ex:words:4:pos":"verb","grammar:3955:ex:words:5:zh":"a thing, an idea","grammar:3955:ex:words:5:pos":"noun","grammar:3955:ex:words:6:zh":"(the target of one's empathy)","grammar:3955:ex:words:6:pos":"particle","grammar:3955:ex:words:7:zh":"(topic marker, contrast)","grammar:3955:ex:words:7:pos":"particle","grammar:3955:ex:words:8:zh":"sympathy, agreement","grammar:3955:ex:words:8:note":"きょうかん","grammar:3955:ex:words:8:pos":"noun","grammar:3955:ex:words:9:zh":"be able to","grammar:3955:ex:words:9:pos":"verb","grammar:3955:ex:words:10:zh":"(polite ending)","grammar:3955:ex:words:10:pos":"auxiliary verb","grammar:3955:ex:points:0":"In a clause that modifies a noun, the subject marker 「が」 can sometimes be replaced with 「の」.","grammar:3955:ex:points:1":"「〜に共感する」 means to feel sympathy for someone's ideas or feelings.","grammar:3955:ex:points:2":"The potential form of 「共感する」 is 「共感できる」.","grammar:3955:ex2:trans":"It's necessary to come up with new ideas.","grammar:3955:ex2:structure":"〜を考える必要があります","grammar:3955:ex2:explain":"「新しい」 modifies 「アイデア」, and 「を」 marks what is being thought up. The whole phrase 「新しいアイデアを考える」 modifies the noun 「必要」, spelling out what needs to be done. 「必要があります」 literally means the necessity exists; overall the sentence says it's necessary to come up with new ideas.","grammar:3955:ex2:words:0:zh":"new","grammar:3955:ex2:words:0:note":"あたらしい","grammar:3955:ex2:words:0:pos":"i-adjective","grammar:3955:ex2:words:1:zh":"ideas","grammar:3955:ex2:words:1:pos":"noun","grammar:3955:ex2:words:2:zh":"(object)","grammar:3955:ex2:words:2:pos":"particle","grammar:3955:ex2:words:3:zh":"to come up with","grammar:3955:ex2:words:3:note":"かんがえる","grammar:3955:ex2:words:3:pos":"verb","grammar:3955:ex2:words:4:zh":"necessary, needed","grammar:3955:ex2:words:4:note":"ひつよう","grammar:3955:ex2:words:4:pos":"noun","grammar:3955:ex2:words:5:zh":"(nominative)","grammar:3955:ex2:words:5:pos":"particle","grammar:3955:ex2:words:6:zh":"there is / are","grammar:3955:ex2:words:6:pos":"verb","grammar:3955:ex2:words:7:zh":"(polite ending)","grammar:3955:ex2:words:7:pos":"auxiliary verb","grammar:3955:ex2:points:0":"「dictionary form of a verb＋必要がある」 means it's necessary to do something.","grammar:3955:ex2:points:1":"Besides meaning to think, 「考える」 can also mean to come up with or think up ideas.","grammar:3955:ex3:trans":"You should think flexibly.","grammar:3955:ex3:structure":"na-adjective＋に＋dictionary form of a verb＋べきです","grammar:3955:ex3:explain":"「柔軟」 is a na-adjective; with 「に」 it means flexibly and modifies 「考える」. 「べき」 follows the dictionary form of a verb and expresses that the speaker thinks this is the right or necessary thing to do. 「です」 makes the ending more polite, but 「べき」 itself still carries a clear tone of advice or norm.","grammar:3955:ex3:words:0:zh":"flexible, pliant","grammar:3955:ex3:words:0:note":"じゅうなん","grammar:3955:ex3:words:0:pos":"na-adjective","grammar:3955:ex3:words:1:zh":"(adverbial use of a na-adjective)","grammar:3955:ex3:words:1:pos":"auxiliary verb","grammar:3955:ex3:words:2:zh":"think","grammar:3955:ex3:words:2:note":"かんがえる","grammar:3955:ex3:words:2:pos":"verb","grammar:3955:ex3:words:3:zh":"(should)","grammar:3955:ex3:words:3:pos":"auxiliary verb","grammar:3955:ex3:words:4:zh":"(polite ending)","grammar:3955:ex3:words:4:pos":"auxiliary verb","grammar:3955:ex3:points:0":"A na-adjective uses 「〜に」 to modify a verb, as in 「柔軟に考える」.","grammar:3955:ex3:points:1":"「dictionary form of a verb＋べきです」 means that, by reason or judgment, something should be done; the tone is fairly strong.","grammar:3955:ex4:trans":"I went and asked him what he thought.","grammar:3955:ex4:structure":"〜がどう〜ているかを聞いてきました","grammar:3955:ex4:explain":"「彼がどう考えているか」 is an embedded question meaning how he thinks; 「が」 marks the subject inside that question. 「を」 marks the whole question as the content of the asking. 「聞いてきました」 means going to ask and then coming back, and in the translation the asker of the main clause is understood to be I.","grammar:3955:ex4:words:0:zh":"he","grammar:3955:ex4:words:0:note":"かれ","grammar:3955:ex4:words:0:pos":"pronoun","grammar:3955:ex4:words:1:zh":"(the subject of the embedded question)","grammar:3955:ex4:words:1:pos":"particle","grammar:3955:ex4:words:2:zh":"how","grammar:3955:ex4:words:2:pos":"adverb","grammar:3955:ex4:words:3:zh":"think","grammar:3955:ex4:words:3:note":"かんがえ","grammar:3955:ex4:words:3:pos":"verb","grammar:3955:ex4:words:4:zh":"(connects to an auxiliary verb)","grammar:3955:ex4:words:4:pos":"particle","grammar:3955:ex4:words:5:zh":"(an ongoing thought)","grammar:3955:ex4:words:5:pos":"verb","grammar:3955:ex4:words:6:zh":"(embedded question)","grammar:3955:ex4:words:6:pos":"particle","grammar:3955:ex4:words:7:zh":"(what is being asked about)","grammar:3955:ex4:words:7:pos":"particle","grammar:3955:ex4:words:8:zh":"ask","grammar:3955:ex4:words:8:note":"きい","grammar:3955:ex4:words:8:pos":"verb","grammar:3955:ex4:words:9:zh":"(connects to an auxiliary verb)","grammar:3955:ex4:words:9:pos":"particle","grammar:3955:ex4:words:10:zh":"(do the action and then come back)","grammar:3955:ex4:words:10:pos":"verb","grammar:3955:ex4:words:11:zh":"(polite)","grammar:3955:ex4:words:11:pos":"auxiliary verb","grammar:3955:ex4:words:12:zh":"(past)","grammar:3955:ex4:words:12:pos":"auxiliary verb","grammar:3955:ex4:points:0":"「question word＋plain form＋か」 lets you put a question inside another sentence.","grammar:3955:ex4:points:1":"「〜かを聞く」 means to ask about the content of that question.","grammar:3955:ex4:points:2":"In this sentence 「〜てくる」 means going to do something and then coming back.","grammar:3955:ex5:trans":"Let's share what we're thinking about.","grammar:3955:ex5:structure":"〜ていることを共有しましょう","grammar:3955:ex5:explain":"「考えている」 modifies the noun 「こと」 and refers to what is being thought about. 「を」 marks what is to be shared. 「共有」 plus 「する」 forms a verb, and its polite suggestion form is 「共有しましょう」, inviting everyone to share their own ideas.","grammar:3955:ex5:words:0:zh":"think","grammar:3955:ex5:words:0:note":"かんがえ","grammar:3955:ex5:words:0:pos":"verb","grammar:3955:ex5:words:1:zh":"(connects to an auxiliary verb)","grammar:3955:ex5:words:1:pos":"particle","grammar:3955:ex5:words:2:zh":"(ongoing, in progress)","grammar:3955:ex5:words:2:pos":"verb","grammar:3955:ex5:words:3:zh":"thing, matter","grammar:3955:ex5:words:3:pos":"noun","grammar:3955:ex5:words:4:zh":"(object)","grammar:3955:ex5:words:4:pos":"particle","grammar:3955:ex5:words:5:zh":"to share","grammar:3955:ex5:words:5:note":"きょうゆう","grammar:3955:ex5:words:5:pos":"noun","grammar:3955:ex5:words:6:zh":"do","grammar:3955:ex5:words:6:pos":"verb","grammar:3955:ex5:words:7:zh":"(polite invitation, suggestion)","grammar:3955:ex5:words:7:pos":"auxiliary verb","grammar:3955:ex5:points:0":"「考えていること」 means the thing you are thinking about, or the idea in your mind.","grammar:3955:ex5:points:1":"「共有する」 means to let each other know or to hold information in common.","grammar:3955:ex5:points:2":"「〜ましょう」 can invite the other person to do something together.","exam:3955:zh":"Since I didn't know the answer to this question, I decided to think about it myself first instead of asking the teacher right away.","exam:3955:why":"「考える」 means to think, which fits trying to work out the answer yourself. 「覚える」 means to memorize, but here the answer isn't known yet—the point is to figure it out first."},"3956":{"example:3956:exzh":"The TV screen is big.","example:3956:exzh2":"Please click on this screen.","example:3956:exzh3":"The movie's visuals are beautiful.","example:3956:exzh4":"The screen is dark, so please make it brighter.","example:3956:exzh5":"I'll share my screen in the online meeting."},"3958":{"example:3958:exzh":"He is a serious student.","example:3958:exzh2":"I'm working seriously.","example:3958:exzh3":"Let's have a serious talk.","example:3958:exzh4":"She has a serious personality.","example:3958:exzh5":"We need to think seriously."},"3959":{"example:3959:exzh":"I'll make potato salad.","example:3959:exzh2":"I like french fries.","example:3959:exzh3":"Boiling potatoes is easy.","example:3959:exzh4":"Potato chips are a snack.","example:3959:exzh5":"He ordered potatoes and meat."},"3960":{"example:3960:exzh":"Egypt is famous for its pyramids.","example:3960:exzh2":"I'm planning a trip to Egypt.","example:3960:exzh3":"Egyptian culture is very interesting.","example:3960:exzh4":"Ancient Egyptian kings were called pharaohs.","example:3960:exzh5":"The Nile in Egypt is the longest river in the world.","grammar:3960:ex:trans":"Egypt is famous for the pyramids.","grammar:3960:ex:structure":"nounは＋noun＋で＋有名です。 〜で有名 = famous for … .","grammar:3960:ex:explain":"The key point is 「〜で有名」, meaning to be famous for, known for something; the thing that makes it famous is marked with 「で」 (showing means or cause), so 「ピラミッドで」 means famous for the pyramids. 「有名」 is a na-adjective, with 「です」 for a polite assertion. The topic 「エジプト」 takes 「は」, and 「ピラミッド」 means pyramid. The sentence says Egypt is famous for the pyramids; 「〜で有名」 is a handy set pattern.","grammar:3960:ex:words:0:zh":"Egypt","grammar:3960:ex:words:0:note":"loanword","grammar:3960:ex:words:0:pos":"noun","grammar:3960:ex:words:1:zh":"(topic marker)","grammar:3960:ex:words:1:pos":"particle","grammar:3960:ex:words:2:zh":"pyramid","grammar:3960:ex:words:2:note":"loanword: pyramid","grammar:3960:ex:words:2:pos":"noun","grammar:3960:ex:words:3:zh":"with","grammar:3960:ex:words:3:note":"by means of","grammar:3960:ex:words:3:pos":"particle","grammar:3960:ex:words:4:zh":"famous","grammar:3960:ex:words:4:note":"ゆうめい","grammar:3960:ex:words:4:pos":"na-adjective","grammar:3960:ex:words:5:zh":"(polite form)","grammar:3960:ex:words:5:pos":"copula","grammar:3960:ex:points:0":"〜で有名: to be famous for … (で marks the grounds)","grammar:3960:ex:points:1":"ピラミッド: pyramid","grammar:3960:ex2:trans":"I'm planning a trip to Egypt.","grammar:3960:ex2:structure":"nounを＋計画しています。 エジプト旅行 = a trip to Egypt.","grammar:3960:ex2:words:0:zh":"a trip to Egypt","grammar:3960:ex2:words:0:note":"エジプトりょこう","grammar:3960:ex2:words:0:pos":"noun","grammar:3960:ex2:words:1:zh":"(object marker)","grammar:3960:ex2:words:1:pos":"particle","grammar:3960:ex2:words:2:zh":"plans","grammar:3960:ex2:words:2:note":"けいかくしています; 〜ている expresses ongoing action","grammar:3960:ex2:words:2:pos":"verb","grammar:3960:ex2:points:0":"計画する: to plan","grammar:3960:ex2:points:1":"〜ている: is …ing","grammar:3960:ex3:trans":"Egyptian culture is very interesting.","grammar:3960:ex3:structure":"〔エジプトの文化〕＋は＋とても＋i-adjective＋です。","grammar:3960:ex3:words:0:zh":"Egypt","grammar:3960:ex3:words:0:note":"loanword","grammar:3960:ex3:words:0:pos":"noun","grammar:3960:ex3:words:1:zh":"'s","grammar:3960:ex3:words:1:pos":"particle","grammar:3960:ex3:words:2:zh":"culture","grammar:3960:ex3:words:2:note":"ぶんか","grammar:3960:ex3:words:2:pos":"noun","grammar:3960:ex3:words:3:zh":"(topic marker)","grammar:3960:ex3:words:3:pos":"particle","grammar:3960:ex3:words:4:zh":"extremely","grammar:3960:ex3:words:4:pos":"adverb","grammar:3960:ex3:words:5:zh":"intriguing","grammar:3960:ex3:words:5:note":"きょうみぶかい","grammar:3960:ex3:words:5:pos":"adjective","grammar:3960:ex3:words:6:zh":"(polite form)","grammar:3960:ex3:words:6:pos":"copula","grammar:3960:ex3:points:0":"興味深い: interesting, intriguing","grammar:3960:ex3:points:1":"エジプトの文化: Egyptian culture","grammar:3960:ex4:trans":"The kings of ancient Egypt were called pharaohs.","grammar:3960:ex4:structure":"〔古代エジプトの王〕＋は＋noun＋と＋呼ばれました。 〜と呼ばれる = to be called … .","grammar:3960:ex4:words:0:zh":"ancient times","grammar:3960:ex4:words:0:note":"こだい","grammar:3960:ex4:words:0:pos":"noun","grammar:3960:ex4:words:1:zh":"Egypt","grammar:3960:ex4:words:1:note":"loanword","grammar:3960:ex4:words:1:pos":"noun","grammar:3960:ex4:words:2:zh":"'s","grammar:3960:ex4:words:2:pos":"particle","grammar:3960:ex4:words:3:zh":"king","grammar:3960:ex4:words:3:note":"おう","grammar:3960:ex4:words:3:pos":"noun","grammar:3960:ex4:words:4:zh":"(topic marker)","grammar:3960:ex4:words:4:pos":"particle","grammar:3960:ex4:words:5:zh":"pharaoh","grammar:3960:ex4:words:5:note":"loanword: pharaoh","grammar:3960:ex4:words:5:pos":"noun","grammar:3960:ex4:words:6:zh":"(quotation)","grammar:3960:ex4:words:6:pos":"particle","grammar:3960:ex4:words:7:zh":"is called","grammar:3960:ex4:words:7:note":"よばれました; passive form","grammar:3960:ex4:words:7:pos":"verb","grammar:3960:ex4:points:0":"〜と呼ばれる: be called… (passive)","grammar:3960:ex4:points:1":"古代エジプト: ancient Egypt","grammar:3960:ex5:trans":"The Nile in Egypt is the longest river in the world.","grammar:3960:ex5:structure":"〔エジプトのナイル川〕＋は＋〔世界で〕＋最も＋i-adjective＋です. 「〜で最も〜」= the most … in …","grammar:3960:ex5:words:0:zh":"Egypt","grammar:3960:ex5:words:0:note":"loanword","grammar:3960:ex5:words:0:pos":"noun","grammar:3960:ex5:words:1:zh":"'s","grammar:3960:ex5:words:1:pos":"particle","grammar:3960:ex5:words:2:zh":"the Nile","grammar:3960:ex5:words:2:note":"ナイルがわ","grammar:3960:ex5:words:2:pos":"noun","grammar:3960:ex5:words:3:zh":"(topic marker)","grammar:3960:ex5:words:3:pos":"particle","grammar:3960:ex5:words:4:zh":"world","grammar:3960:ex5:words:4:note":"せかい","grammar:3960:ex5:words:4:pos":"noun","grammar:3960:ex5:words:5:zh":"(scope)","grammar:3960:ex5:words:5:pos":"particle","grammar:3960:ex5:words:6:zh":"the most","grammar:3960:ex5:words:6:note":"もっとも","grammar:3960:ex5:words:6:pos":"adverb","grammar:3960:ex5:words:7:zh":"long","grammar:3960:ex5:words:7:note":"ながい","grammar:3960:ex5:words:7:pos":"adjective","grammar:3960:ex5:words:8:zh":"(polite form)","grammar:3960:ex5:words:8:pos":"copula","grammar:3960:ex5:points:0":"〜で最も〜: the most … in … (世界で最も長い = the longest in the world)","grammar:3960:ex5:points:1":"最も: most (written style)"},"3962":{"example:3962:exzh":"The blade of this knife is sharp.","example:3962:exzh2":"The blade needs to be replaced.","example:3962:exzh3":"Blade maintenance is important.","example:3962:exzh4":"I'm going to buy a new blade.","example:3962:exzh5":"This blade cuts well."},"3963":{"example:3963:exzh":"You can pass through this road.","example:3963:exzh2":"Did you see the \"through passage\" sign?","example:3963:exzh3":"Passing through that park is prohibited.","example:3963:exzh4":"Please be careful when passing through.","example:3963:exzh5":"Passing through went smoothly."},"3964":{"example:3964:exzh":"He gave a speech at the meeting.","example:3964:exzh2":"The speech was very moving.","example:3964:exzh3":"I heard the president's speech.","example:3964:exzh4":"I need to prepare a speech.","example:3964:exzh5":"She delivered the speech successfully."},"3965":{"example:3965:exzh":"This spring is strong.","example:3965:exzh2":"There are toys that use springs.","example:3965:exzh3":"I bought a new spring.","example:3965:exzh4":"I learned how springs work.","example:3965:exzh5":"This machine needs a spring."},"3966":{"example:3966:exzh":"Believe in yourself.","example:3966:exzh2":"He told me to believe her.","example:3966:exzh3":"Believe in friends.","example:3966:exzh4":"Believe in your dreams.","example:3966:exzh5":"Sometimes it's better to believe.","grammar:3966:ex:trans":"Believe in yourself.","grammar:3966:ex:structure":"〜を信じろ","grammar:3966:ex:explain":"The key point is the imperative form 「信じろ」 of the transitive verb 「信じる」, a strong command or rallying cry: believe (already)! Here it carries an encouraging, pep-talk tone: believe in yourself. 「信じる」 is an ichidan (ru-) verb, and the imperative replaces the final 「る」 with 「ろ」. The object 「自分」 (oneself) takes 「を」. The sentence is a call to have confidence, and the use and tone of the imperative 「〜ろ」 is the main point; it's common in motivational settings.","grammar:3966:ex:words:0:zh":"oneself","grammar:3966:ex:words:0:note":"じぶん","grammar:3966:ex:words:0:pos":"pronoun","grammar:3966:ex:words:1:zh":"(object marker)","grammar:3966:ex:words:1:pos":"particle","grammar:3966:ex:words:2:zh":"believe (imperative)","grammar:3966:ex:words:2:note":"しんじろ","grammar:3966:ex:words:2:pos":"verb","grammar:3966:ex:points:0":"❗信じる (しんじる): to believe, to trust (transitive verb); 信じろ = believe (imperative form, rallying tone).","grammar:3966:ex:points:1":"自分を信じろ: believe in yourself.","grammar:3966:ex2:trans":"He told me to believe her.","grammar:3966:ex2:structure":"〜を信じろと言った","grammar:3966:ex2:words:0:zh":"he","grammar:3966:ex2:words:0:note":"かれ","grammar:3966:ex2:words:0:pos":"pronoun","grammar:3966:ex2:words:1:zh":"(topic)","grammar:3966:ex2:words:1:pos":"particle","grammar:3966:ex2:words:2:zh":"she","grammar:3966:ex2:words:2:note":"かのじょ","grammar:3966:ex2:words:2:pos":"pronoun","grammar:3966:ex2:words:3:zh":"(object marker)","grammar:3966:ex2:words:3:pos":"particle","grammar:3966:ex2:words:4:zh":"believe (command)","grammar:3966:ex2:words:4:note":"しんじろ","grammar:3966:ex2:words:4:pos":"verb","grammar:3966:ex2:words:5:zh":"(quotation)","grammar:3966:ex2:words:5:pos":"particle","grammar:3966:ex2:words:6:zh":"said","grammar:3966:ex2:words:6:note":"いった","grammar:3966:ex2:words:6:pos":"verb","grammar:3966:ex2:points:0":"❗〜と言った: said that… (quoting a command); 彼女を信じろ = believe her.","grammar:3966:ex2:points:1":"信じろと言う: to tell someone to believe.","grammar:3966:ex3:trans":"Believe in friends.","grammar:3966:ex3:structure":"〜を信じろ","grammar:3966:ex3:words:0:zh":"friend","grammar:3966:ex3:words:0:note":"ともだち","grammar:3966:ex3:words:0:pos":"noun","grammar:3966:ex3:words:1:zh":"(object marker)","grammar:3966:ex3:words:1:pos":"particle","grammar:3966:ex3:words:2:zh":"believe (imperative)","grammar:3966:ex3:words:2:note":"しんじろ","grammar:3966:ex3:words:2:pos":"verb","grammar:3966:ex3:points:0":"❗友達を信じる: to trust a friend; 信じろ = believe (imperative).","grammar:3966:ex3:points:1":"友達を信じろ: believe in friends.","grammar:3966:ex4:trans":"Believe in dreams.","grammar:3966:ex4:structure":"〜を信じろ","grammar:3966:ex4:words:0:zh":"dream","grammar:3966:ex4:words:0:note":"ゆめ","grammar:3966:ex4:words:0:pos":"noun","grammar:3966:ex4:words:1:zh":"(object marker)","grammar:3966:ex4:words:1:pos":"particle","grammar:3966:ex4:words:2:zh":"believe (imperative)","grammar:3966:ex4:words:2:note":"しんじろ","grammar:3966:ex4:words:2:pos":"verb","grammar:3966:ex4:points:0":"❗夢を信じる: to believe in a dream; 信じろ = imperative form used to encourage.","grammar:3966:ex4:points:1":"夢を信じろ: believe in a dream.","grammar:3966:ex5:trans":"Sometimes it's better to believe.","grammar:3966:ex5:structure":"時には信じた方がいい","grammar:3966:ex5:words:0:zh":"sometimes","grammar:3966:ex5:words:0:note":"ときには","grammar:3966:ex5:words:0:pos":"adverb","grammar:3966:ex5:words:1:zh":"believe","grammar:3966:ex5:words:1:note":"しんじた","grammar:3966:ex5:words:1:pos":"verb","grammar:3966:ex5:words:2:zh":"it's better to","grammar:3966:ex5:words:2:note":"ほうがいい","grammar:3966:ex5:words:2:pos":"set phrase","grammar:3966:ex5:points:0":"❗〜た方がいい: had better…, it's best to…; 時には = sometimes.","grammar:3966:ex5:points:1":"信じた方がいい: it's better to believe."},"3967":{"example:3967:exzh":"I confided the secret to her.","example:3967:exzh2":"Let's open up about our true feelings.","example:3967:exzh3":"I confided my worries to a friend.","example:3967:exzh4":"He seems unable to open up about what's in his heart.","example:3967:exzh5":"Thank you for opening up to me about this."},"3968":{"example:3968:exzh":"The police seized the evidence.","example:3968:exzh2":"The seized items will be returned later.","example:3968:exzh3":"The seizure procedure is complicated.","example:3968:exzh4":"I checked the seized documents.","example:3968:exzh5":"Please explain the reason for the seizure."},"3969":{"example:3969:exzh":"He is undergoing rehabilitation after the accident.","example:3969:exzh2":"Rehabilitation is extremely important.","example:3969:exzh3":"The effects of rehabilitation are starting to show.","example:3969:exzh4":"I go to rehabilitation every day.","example:3969:exzh5":"Once rehabilitation is over, I'll be able to exercise again."},"3970":{"example:3970:exzh":"She needs an organ transplant.","example:3970:exzh2":"The transplant surgery was successful.","example:3970:exzh3":"A transplant donor was found.","example:3970:exzh4":"Recovery is going smoothly after the transplant.","example:3970:exzh5":"He waited a long time for a transplant."},"3971":{"example:3971:exzh":"He went to cover a new movie.","example:3971:exzh2":"I'll report the results of the interview.","example:3971:exzh3":"I talked with many people at the interview site.","example:3971:exzh4":"I'll turn what I covered into an article.","example:3971:exzh5":"She interviewed a famous author."},"3972":{"example:3972:exzh":"He is the section manager for the project.","example:3972:exzh2":"I've submitted the report to the section manager.","example:3972:exzh3":"The section manager values feedback from subordinates.","example:3972:exzh4":"A new section manager has taken office.","example:3972:exzh5":"The section manager will hold a meeting."},"3973":{"example:3973:exzh":"I'm re-watching the recording.","example:3973:exzh2":"This program has been recorded.","example:3973:exzh3":"I've saved the recording data.","example:3973:exzh4":"I used a video camera to capture happy memories.","example:3973:exzh5":"A recording of the class is needed."},"3974":{"example:3974:exzh":"I'm looking for a place where the bus stops.","example:3974:exzh2":"The car can stop here.","example:3974:exzh3":"He suddenly brought the car to a stop.","example:3974:exzh4":"When I got to the station, the train was stopped.","example:3974:exzh5":"That shop stays open late, and cars can stop in front of it at any time.","grammar:3974:ex:trans":"I'm looking for a place where the bus stops.","grammar:3974:ex:structure":"〜が停まる場所","grammar:3974:ex:explain":"The key is the intransitive verb 「停まる」, which means that a vehicle stops or pulls in on its own, with the subject 「バス」 marked by 「が」. 「バスが停まる」 is a relative clause modifying 「場所」, forming the place where the bus stops. Note that the subject inside a modifying clause takes 「が」. 「探している」 is the te-form of 「探す」 plus 「いる」, showing an action in progress. The sentence says someone is looking for a bus stop, and the intransitive verb plus the relative clause are the key points.","grammar:3974:ex:words:0:zh":"bus","grammar:3974:ex:words:0:note":"loanword","grammar:3974:ex:words:0:pos":"noun","grammar:3974:ex:words:1:zh":"(nominative)","grammar:3974:ex:words:1:pos":"particle","grammar:3974:ex:words:2:zh":"stop","grammar:3974:ex:words:2:note":"とまる","grammar:3974:ex:words:2:pos":"verb","grammar:3974:ex:words:3:zh":"place","grammar:3974:ex:words:3:note":"ばしょ","grammar:3974:ex:words:3:pos":"noun","grammar:3974:ex:words:4:zh":"(object marker)","grammar:3974:ex:words:4:pos":"particle","grammar:3974:ex:words:5:zh":"are looking for","grammar:3974:ex:words:5:note":"さがしている","grammar:3974:ex:words:5:pos":"verb","grammar:3974:ex:points:0":"❗停まる (intransitive verb: a vehicle stops by itself); バスが停まる: the bus stops.","grammar:3974:ex:points:1":"場所を探す: to look for a place.","grammar:3974:ex2:trans":"A car may stop here.","grammar:3974:ex2:structure":"〜で停まってもいい","grammar:3974:ex2:explain":"「ここで」 indicates the place where the stopping happens. 「停まってもいい」 literally means it's fine even if it stops, so it expresses that stopping here is allowed; the more polite version is 「停まってもいいです」.","grammar:3974:ex2:words:0:zh":"car","grammar:3974:ex2:words:0:note":"くるま","grammar:3974:ex2:words:0:pos":"noun","grammar:3974:ex2:words:1:zh":"(topic)","grammar:3974:ex2:words:1:pos":"particle","grammar:3974:ex2:words:2:zh":"here","grammar:3974:ex2:words:2:pos":"pronoun","grammar:3974:ex2:words:3:zh":"(place of the action)","grammar:3974:ex2:words:3:pos":"particle","grammar:3974:ex2:words:4:zh":"stop","grammar:3974:ex2:words:4:note":"とまっ","grammar:3974:ex2:words:4:pos":"verb","grammar:3974:ex2:words:5:zh":"(te-form link)","grammar:3974:ex2:words:5:pos":"particle","grammar:3974:ex2:words:6:zh":"(even so)","grammar:3974:ex2:words:6:pos":"particle","grammar:3974:ex2:words:7:zh":"may, it's fine","grammar:3974:ex2:words:7:pos":"i-adjective","grammar:3974:ex2:points:0":"「動詞て形＋もいい」 expresses that doing something is allowed.","grammar:3974:ex2:points:1":"「停まる」 is an intransitive verb describing a car coming to a stop.","grammar:3974:ex3:trans":"He suddenly brought the car to a stop.","grammar:3974:ex3:structure":"〜を停まらせた","grammar:3974:ex3:words:0:zh":"he","grammar:3974:ex3:words:0:note":"かれ","grammar:3974:ex3:words:0:pos":"pronoun","grammar:3974:ex3:words:1:zh":"(topic)","grammar:3974:ex3:words:1:pos":"particle","grammar:3974:ex3:words:2:zh":"suddenly","grammar:3974:ex3:words:2:note":"きゅうに","grammar:3974:ex3:words:2:pos":"adverb","grammar:3974:ex3:words:3:zh":"car","grammar:3974:ex3:words:3:note":"くるま","grammar:3974:ex3:words:3:pos":"noun","grammar:3974:ex3:words:4:zh":"(object marker)","grammar:3974:ex3:words:4:pos":"particle","grammar:3974:ex3:words:5:zh":"make … stop","grammar:3974:ex3:words:5:note":"とまらせた (causative)","grammar:3974:ex3:words:5:pos":"verb","grammar:3974:ex3:points:0":"❗停まらせる: to make (a car) stop (the causative of 停まる); you can also simply use the transitive verb 「止めた」.","grammar:3974:ex3:points:1":"急に: suddenly.","grammar:3974:ex4:trans":"When I got to the station, the train was stopped.","grammar:3974:ex4:structure":"〜が止まっていた","grammar:3974:ex4:words:0:zh":"station","grammar:3974:ex4:words:0:note":"えき","grammar:3974:ex4:words:0:pos":"noun","grammar:3974:ex4:words:1:zh":"(the destination point)","grammar:3974:ex4:words:1:pos":"particle","grammar:3974:ex4:words:2:zh":"when (someone) arrived","grammar:3974:ex4:words:2:note":"ついたら","grammar:3974:ex4:words:2:pos":"verb","grammar:3974:ex4:words:3:zh":"train","grammar:3974:ex4:words:3:note":"でんしゃ","grammar:3974:ex4:words:3:pos":"noun","grammar:3974:ex4:words:4:zh":"(nominative)","grammar:3974:ex4:words:4:pos":"particle","grammar:3974:ex4:words:5:zh":"was stopped","grammar:3974:ex4:words:5:note":"とまっていた","grammar:3974:ex4:words:5:pos":"verb","grammar:3974:ex4:points:0":"❗止まる (intransitive verb: to stop); 電車が止まる: the train stops.","grammar:3974:ex4:points:1":"〜たら: after …","grammar:3974:ex5:trans":"That shop stays open until late, and a car can park in front of it at any time.","grammar:3974:ex5:structure":"〜は夜遅くまで開いていて、〜にはいつでも車が停まれる","grammar:3974:ex5:explain":"「夜遅くまで」 means the shop stays open until late at night, and 「開いていて」 links that open state to what follows. 「店の前には」 presents the place where a car can park, and 「車が停まれる」 means a car can park there; the potential form focuses on whether it's physically possible, so whether parking is officially permitted still depends on the situation.","grammar:3974:ex5:words:0:zh":"that","grammar:3974:ex5:words:0:pos":"pre-noun adjectival","grammar:3974:ex5:words:1:zh":"store","grammar:3974:ex5:words:1:note":"みせ","grammar:3974:ex5:words:1:pos":"noun","grammar:3974:ex5:words:2:zh":"(topic)","grammar:3974:ex5:words:2:pos":"particle","grammar:3974:ex5:words:3:zh":"evening","grammar:3974:ex5:words:3:note":"よる","grammar:3974:ex5:words:3:pos":"noun","grammar:3974:ex5:words:4:zh":"late","grammar:3974:ex5:words:4:note":"おそく","grammar:3974:ex5:words:4:pos":"i-adjective","grammar:3974:ex5:words:5:zh":"(end point in time) until","grammar:3974:ex5:words:5:pos":"particle","grammar:3974:ex5:words:6:zh":"open, in business","grammar:3974:ex5:words:6:note":"あい","grammar:3974:ex5:words:6:pos":"verb","grammar:3974:ex5:words:7:zh":"(links a state)","grammar:3974:ex5:words:7:pos":"particle","grammar:3974:ex5:words:8:zh":"keeps that state","grammar:3974:ex5:words:8:pos":"verb","grammar:3974:ex5:words:9:zh":"(links to the next clause)","grammar:3974:ex5:words:9:pos":"particle","grammar:3974:ex5:words:10:zh":"store","grammar:3974:ex5:words:10:note":"みせ","grammar:3974:ex5:words:10:pos":"noun","grammar:3974:ex5:words:11:zh":"(place modifier)","grammar:3974:ex5:words:11:pos":"particle","grammar:3974:ex5:words:12:zh":"front","grammar:3974:ex5:words:12:note":"まえ","grammar:3974:ex5:words:12:pos":"noun","grammar:3974:ex5:words:13:zh":"(parking spot)","grammar:3974:ex5:words:13:pos":"particle","grammar:3974:ex5:words:14:zh":"(brings up and highlights the place)","grammar:3974:ex5:words:14:pos":"particle","grammar:3974:ex5:words:15:zh":"when","grammar:3974:ex5:words:15:pos":"pronoun","grammar:3974:ex5:words:16:zh":"(no restriction) any …","grammar:3974:ex5:words:16:pos":"particle","grammar:3974:ex5:words:17:zh":"car","grammar:3974:ex5:words:17:note":"くるま","grammar:3974:ex5:words:17:pos":"noun","grammar:3974:ex5:words:18:zh":"(nominative)","grammar:3974:ex5:words:18:pos":"particle","grammar:3974:ex5:words:19:zh":"can stop, can park","grammar:3974:ex5:words:19:note":"とまれる","grammar:3974:ex5:words:19:pos":"verb","grammar:3974:ex5:points:0":"「開いている」 shows that the shop is open or in business, and 「開いていて」 links it to the next clause.","grammar:3974:ex5:points:1":"「停まれる」 is the potential form of 「停まる」, meaning it's possible to park there under the circumstances.","grammar:3974:ex5:points:2":"「いつでも」 means at any time, without limiting it to a particular time."},"3975":{"example:3975:exzh":"The child is playing with a toy.","example:3975:exzh2":"This toy is very popular.","example:3975:exzh3":"My dog likes chewing on toys.","example:3975:exzh4":"Help me put the toys away.","example:3975:exzh5":"That toy broke.","grammar:3975:ex:trans":"The child is playing with a toy.","grammar:3975:ex:structure":"〜は＋noun＋で＋遊んでいる. 「〜で遊ぶ」= to play with …","grammar:3975:ex:explain":"The key point is 「〜で遊ぶ」, meaning to play with …; the tool or toy used for playing takes 「で」, so here 「オモチャで」 means with a toy. 「遊んでいる」 is the te-form of 「遊ぶ」 plus 「いる」, showing an action in progress (is playing). 「オモチャ」 means toy. The topic 「子供」 takes 「は」. The whole sentence says the child is playing with a toy; the important point is that 「で」 marks the toy being played with, so don't mistakenly use 「を」.","grammar:3975:ex:words:0:zh":"child","grammar:3975:ex:words:0:note":"こども","grammar:3975:ex:words:0:pos":"noun","grammar:3975:ex:words:1:zh":"(topic marker)","grammar:3975:ex:words:1:pos":"particle","grammar:3975:ex:words:2:zh":"toy","grammar:3975:ex:words:2:note":"katakana","grammar:3975:ex:words:2:pos":"noun","grammar:3975:ex:words:3:zh":"use","grammar:3975:ex:words:3:note":"means / tool","grammar:3975:ex:words:3:pos":"particle","grammar:3975:ex:words:4:zh":"hang out","grammar:3975:ex:words:4:note":"〜ている marks an ongoing action","grammar:3975:ex:words:4:pos":"verb","grammar:3975:ex:points:0":"〜で遊ぶ: to play with … (オモチャで遊ぶ = to play with toys)","grammar:3975:ex:points:1":"〜ている: is …ing","grammar:3975:ex2:trans":"This toy is very popular.","grammar:3975:ex2:structure":"この＋noun＋は＋とても＋人気です.","grammar:3975:ex2:words:0:zh":"this","grammar:3975:ex2:words:0:pos":"pre-noun adjectival","grammar:3975:ex2:words:1:zh":"toy","grammar:3975:ex2:words:1:note":"katakana","grammar:3975:ex2:words:1:pos":"noun","grammar:3975:ex2:words:2:zh":"(topic marker)","grammar:3975:ex2:words:2:pos":"particle","grammar:3975:ex2:words:3:zh":"extremely","grammar:3975:ex2:words:3:pos":"adverb","grammar:3975:ex2:words:4:zh":"popular","grammar:3975:ex2:words:4:note":"にんき","grammar:3975:ex2:words:4:pos":"na-adjective","grammar:3975:ex2:words:5:zh":"(polite form)","grammar:3975:ex2:words:5:pos":"copula","grammar:3975:ex2:points:0":"人気です: is popular","grammar:3975:ex2:points:1":"このオモチャ: this toy","grammar:3975:ex3:trans":"My dog likes chewing on toys.","grammar:3975:ex3:structure":"〔私の犬〕＋は＋〔オモチャを噛む＋の〕＋が＋好きです.","grammar:3975:ex3:words:0:zh":"I","grammar:3975:ex3:words:0:note":"わたし","grammar:3975:ex3:words:0:pos":"pronoun","grammar:3975:ex3:words:1:zh":"'s","grammar:3975:ex3:words:1:pos":"particle","grammar:3975:ex3:words:2:zh":"dog","grammar:3975:ex3:words:2:note":"いぬ","grammar:3975:ex3:words:2:pos":"noun","grammar:3975:ex3:words:3:zh":"(topic marker)","grammar:3975:ex3:words:3:pos":"particle","grammar:3975:ex3:words:4:zh":"toy","grammar:3975:ex3:words:4:note":"katakana","grammar:3975:ex3:words:4:pos":"noun","grammar:3975:ex3:words:5:zh":"(object marker)","grammar:3975:ex3:words:5:pos":"particle","grammar:3975:ex3:words:6:zh":"bite","grammar:3975:ex3:words:6:note":"かむ","grammar:3975:ex3:words:6:pos":"verb","grammar:3975:ex3:words:7:zh":"(nominalizer)","grammar:3975:ex3:words:7:pos":"particle","grammar:3975:ex3:words:8:zh":"(object marker)","grammar:3975:ex3:words:8:pos":"particle","grammar:3975:ex3:words:9:zh":"to like","grammar:3975:ex3:words:9:note":"すき","grammar:3975:ex3:words:9:pos":"na-adjective","grammar:3975:ex3:words:10:zh":"(polite form)","grammar:3975:ex3:words:10:pos":"copula","grammar:3975:ex3:points:0":"verb + の + が好き: like doing…","grammar:3975:ex3:points:1":"噛む: to bite","grammar:3975:ex4:trans":"Help me put the toys away.","grammar:3975:ex4:structure":"〔オモチャを片付ける＋の〕＋を＋手伝って. 「〜のを手伝う」= to help do …, with the te-form used as a casual request.","grammar:3975:ex4:words:0:zh":"toy","grammar:3975:ex4:words:0:note":"katakana","grammar:3975:ex4:words:0:pos":"noun","grammar:3975:ex4:words:1:zh":"(object marker)","grammar:3975:ex4:words:1:pos":"particle","grammar:3975:ex4:words:2:zh":"put away","grammar:3975:ex4:words:2:note":"かたづける; dictionary form","grammar:3975:ex4:words:2:pos":"verb","grammar:3975:ex4:words:3:zh":"(nominalizer)","grammar:3975:ex4:words:3:pos":"particle","grammar:3975:ex4:words:4:zh":"(object marker)","grammar:3975:ex4:words:4:pos":"particle","grammar:3975:ex4:words:5:zh":"help","grammar:3975:ex4:words:5:note":"てつだって; te-form (casual request)","grammar:3975:ex4:words:5:pos":"verb","grammar:3975:ex4:points:0":"〜のを手伝う: help (do) …","grammar:3975:ex4:points:1":"片付ける: to tidy up, to put away","grammar:3975:ex5:trans":"That toy broke.","grammar:3975:ex5:structure":"その＋noun＋は＋〜てしまった. 「壊れる」 is an intransitive verb, and 「〜てしまった」 expresses regret.","grammar:3975:ex5:words:0:zh":"that","grammar:3975:ex5:words:0:pos":"pre-noun adjectival","grammar:3975:ex5:words:1:zh":"toy","grammar:3975:ex5:words:1:note":"katakana","grammar:3975:ex5:words:1:pos":"noun","grammar:3975:ex5:words:2:zh":"(topic marker)","grammar:3975:ex5:words:2:pos":"particle","grammar:3975:ex5:words:3:zh":"broke (with regret)","grammar:3975:ex5:words:3:note":"こわれてしまった；〜てしまう","grammar:3975:ex5:words:3:pos":"verb","grammar:3975:ex5:points:0":"壊れる: (intransitive verb) break","grammar:3975:ex5:points:1":"〜てしまった: (regrettably) did …"},"3976":{"example:3976:exzh":"A cowboy is a character in Westerns.","example:3976:exzh2":"He is wearing cowboy clothes.","example:3976:exzh3":"The kids are enjoying playing cowboys.","example:3976:exzh4":"In the movie, a cowboy is riding a horse.","example:3976:exzh5":"I like wearing a cowboy hat."},"3977":{"example:3977:exzh":"I thought his idea was crazy.","example:3977:exzh2":"This game is crazy and fun.","example:3977:exzh3":"It was just a crazy night.","example:3977:exzh4":"She's a fun, crazy person.","example:3977:exzh5":"Let's make a crazy plan."},"3978":{"example:3978:exzh":"Her hair is ash-colored.","example:3978:exzh2":"Ash is a very popular color.","example:3978:exzh3":"The ash blend is a special tone.","example:3978:exzh4":"This wall is ash gray.","example:3978:exzh5":"Ash gives a calm impression."},"3981":{"example:3981:exzh":"That rule must be followed strictly.","example:3981:exzh2":"A strict schedule is needed.","example:3981:exzh3":"This project requires strict standards.","example:3981:exzh4":"It's important to investigate rigorously.","example:3981:exzh5":"A strict evaluation is needed."},"3982":{"example:3982:exzh":"The countdown has begun.","example:3982:exzh2":"He got the count wrong.","example:3982:exzh3":"I like counting.","example:3982:exzh4":"The final count is important.","example:3982:exzh5":"Please keep counting."},"3983":{"example:3983:exzh":"That was a close call.","example:3983:exzh2":"He's in a dangerous situation.","example:3983:exzh3":"I felt a hint of danger.","example:3983:exzh4":"I almost had an accident.","example:3983:exzh5":"This road is dangerous."},"3984":{"example:3984:exzh":"The scene in the movie was impressive.","example:3984:exzh2":"I remember this scene.","example:3984:exzh3":"The scene changes.","example:3984:exzh4":"That scene was very moving.","example:3984:exzh5":"Try describing this scene."},"3985":{"example:3985:exzh":"She always compliments me.","example:3985:exzh2":"It's important to praise children.","example:3985:exzh3":"I praised a friend.","example:3985:exzh4":"It feels good to be praised.","example:3985:exzh5":"When I praised him, he got embarrassed.","grammar:3985:ex:trans":"She always praises me.","grammar:3985:ex:structure":"〜を褒めてくれる","grammar:3985:ex:explain":"There are two key points. First, the transitive verb 「褒める」 (to praise, to compliment), with the object 「私」 taking 「を」. Second, the auxiliary verb of giving and receiving 「〜てくれる」, meaning someone does something for me and carrying a nuance of gratitude and benefit; here 「褒めてくれる」 means she (willingly) praises me. The adverb 「いつも」 means always. The topic 「彼女」 takes 「は」. The sentence says she always praises me, and the benefactive nuance of 「〜てくれる」 is the main point.","grammar:3985:ex:words:0:zh":"she","grammar:3985:ex:words:0:note":"かのじょ","grammar:3985:ex:words:0:pos":"pronoun","grammar:3985:ex:words:1:zh":"(topic)","grammar:3985:ex:words:1:pos":"particle","grammar:3985:ex:words:2:zh":"always","grammar:3985:ex:words:2:pos":"adverb","grammar:3985:ex:words:3:zh":"I","grammar:3985:ex:words:3:note":"わたし","grammar:3985:ex:words:3:pos":"pronoun","grammar:3985:ex:words:4:zh":"(object marker)","grammar:3985:ex:words:4:pos":"particle","grammar:3985:ex:words:5:zh":"to praise","grammar:3985:ex:words:5:note":"ほめて","grammar:3985:ex:words:5:pos":"verb","grammar:3985:ex:words:6:zh":"makes (for me)","grammar:3985:ex:words:6:pos":"auxiliary verb","grammar:3985:ex:points:0":"❗褒める (ほめる): to praise, to compliment (transitive verb); 〜てくれる = to do… (for me); 私を褒める = to praise me.","grammar:3985:ex:points:1":"私を褒める: to praise me.","grammar:3985:ex2:trans":"Praising children is important.","grammar:3985:ex2:structure":"〜を褒めることが大切です","grammar:3985:ex2:words:0:zh":"child","grammar:3985:ex2:words:0:note":"こども","grammar:3985:ex2:words:0:pos":"noun","grammar:3985:ex2:words:1:zh":"(object marker)","grammar:3985:ex2:words:1:pos":"particle","grammar:3985:ex2:words:2:zh":"to praise","grammar:3985:ex2:words:2:note":"ほめる","grammar:3985:ex2:words:2:pos":"verb","grammar:3985:ex2:words:3:zh":"(nominalizer)","grammar:3985:ex2:words:3:pos":"noun","grammar:3985:ex2:words:4:zh":"(nominative)","grammar:3985:ex2:words:4:pos":"particle","grammar:3985:ex2:words:5:zh":"important","grammar:3985:ex2:words:5:note":"たいせつ","grammar:3985:ex2:words:5:pos":"na-adjective","grammar:3985:ex2:words:6:zh":"(polite form)","grammar:3985:ex2:words:6:pos":"copula","grammar:3985:ex2:points:0":"❗子供を褒める: to praise a child; 〜が大切 = … is important.","grammar:3985:ex2:points:1":"子供を褒める: to praise a child.","grammar:3985:ex3:trans":"I praised a friend.","grammar:3985:ex3:structure":"〜を褒めた","grammar:3985:ex3:words:0:zh":"friend","grammar:3985:ex3:words:0:note":"ともだち","grammar:3985:ex3:words:0:pos":"noun","grammar:3985:ex3:words:1:zh":"(object marker)","grammar:3985:ex3:words:1:pos":"particle","grammar:3985:ex3:words:2:zh":"praised","grammar:3985:ex3:words:2:note":"ほめた","grammar:3985:ex3:words:2:pos":"verb","grammar:3985:ex3:points:0":"❗友達を褒める: to praise a friend.","grammar:3985:ex3:points:1":"友達を褒める: to praise a friend.","grammar:3985:ex4:trans":"It feels good to be praised.","grammar:3985:ex4:structure":"褒められると嬉しいです","grammar:3985:ex4:words:0:zh":"being praised","grammar:3985:ex4:words:0:note":"ほめられる","grammar:3985:ex4:words:0:pos":"verb","grammar:3985:ex4:words:1:zh":"(as soon as…)","grammar:3985:ex4:words:1:pos":"particle","grammar:3985:ex4:words:2:zh":"happy","grammar:3985:ex4:words:2:note":"うれしい","grammar:3985:ex4:words:2:pos":"adjective","grammar:3985:ex4:words:3:zh":"(polite form)","grammar:3985:ex4:words:3:pos":"copula","grammar:3985:ex4:points:0":"❗褒められる: to be praised (the passive form of 褒める); 〜と = whenever…, then….","grammar:3985:ex4:points:1":"褒められる: to be praised.","grammar:3985:ex5:trans":"When I praised him, he got shy.","grammar:3985:ex5:structure":"〜を褒めたら照れていた","grammar:3985:ex5:words:0:zh":"he","grammar:3985:ex5:words:0:note":"かれ","grammar:3985:ex5:words:0:pos":"pronoun","grammar:3985:ex5:words:1:zh":"(object marker)","grammar:3985:ex5:words:1:pos":"particle","grammar:3985:ex5:words:2:zh":"when (I) praised (him)","grammar:3985:ex5:words:2:note":"ほめたら","grammar:3985:ex5:words:2:pos":"verb","grammar:3985:ex5:words:3:zh":"was being shy","grammar:3985:ex5:words:3:note":"てれていた","grammar:3985:ex5:words:3:pos":"verb","grammar:3985:ex5:points:0":"❗〜たら: after…, if… then…; 照れる = to be shy, to feel embarrassed.","grammar:3985:ex5:points:1":"褒めたら照れる: praise him and he blushes."},"3986":{"example:3986:exzh":"Discrimination is unacceptable.","example:3986:exzh2":"She is against discrimination.","example:3986:exzh3":"Let's work to eliminate discrimination.","example:3986:exzh4":"Issues related to discrimination are very important.","example:3986:exzh5":"Education is needed to eliminate discrimination."},"3987":{"example:3987:exzh":"This pillar is extremely sturdy.","example:3987:exzh2":"I drew a picture on the pillar.","example:3987:exzh3":"The pillar is about to fall.","example:3987:exzh4":"The old pillar gives you a sense of history.","example:3987:exzh5":"There's a gap between the pillar and the wall."},"3988":{"example:3988:exzh":"Lightning flashed across the sky.","example:3988:exzh2":"I heard the sound of lightning.","example:3988:exzh3":"I saw the lightning flash.","example:3988:exzh4":"I'm scared of lightning.","example:3988:exzh5":"After the lightning, thunder rumbled."},"3989":{"example:3989:exzh":"You should behave properly in public.","example:3989:exzh2":"It's important to listen to public opinion.","example:3989:exzh3":"We must consider the public interest.","example:3989:exzh4":"Let's use public transportation.","example:3989:exzh5":"Think about how to behave in public."},"3990":{"example:3990:exzh":"Halloween is coming up.","example:3990:exzh2":"The kids prepared costumes for Halloween.","example:3990:exzh3":"Putting up Halloween decorations is fun.","example:3990:exzh4":"This year's Halloween is special.","example:3990:exzh5":"I got candy on Halloween."},"3991":{"example:3991:exzh":"Last night I dreamed that I was having a good time with my friends.","example:3991:exzh2":"The life I had been dreaming of finally became real.","example:3991:exzh3":"He seems to have all kinds of dreams every night.","example:3991:exzh4":"Dreaming refreshes the mind.","example:3991:exzh5":"When I was a child, I dreamed of becoming an astronaut."},"3992":{"example:3992:exzh":"He regrets his own decision.","example:3992:exzh2":"There's no use regretting it.","example:3992:exzh3":"It's natural to regret a big mistake.","example:3992:exzh4":"She regretted her decision, but it was already too late.","example:3992:exzh5":"Moving forward matters more than feelings of regret."},"3993":{"example:3993:exzh":"After it rained, the ground dried.","example:3993:exzh2":"Hair dries right away.","example:3993:exzh3":"These clothes take time to dry.","example:3993:exzh4":"The ground dries quickly in the wind.","example:3993:exzh5":"Let's wait here until the clothes dry.","grammar:3993:ex:trans":"After it rained, the ground dried.","grammar:3993:ex:structure":"〜が乾いた","grammar:3993:ex:explain":"The key point is the intransitive verb 「乾く」, meaning (for an object) to become dry, with the subject 「地面」 taking 「が」. Be careful: it differs in kanji and meaning from the homophone 「渇く」 (to be thirsty), so don't mix them up. 「乾いた」 is the plain past form. The first half 「雨が降った後」 uses 「〜た後」 meaning after…. The sentence says the ground dried after the rain, and telling apart the homophones 乾く (things dry) and 渇く (to be thirsty) is the core point.","grammar:3993:ex:words:0:zh":"rain","grammar:3993:ex:words:0:note":"あめ","grammar:3993:ex:words:0:pos":"noun","grammar:3993:ex:words:1:zh":"(nominative)","grammar:3993:ex:words:1:pos":"particle","grammar:3993:ex:words:2:zh":"fell","grammar:3993:ex:words:2:note":"ふった","grammar:3993:ex:words:2:pos":"verb","grammar:3993:ex:words:3:zh":"later, afterwards","grammar:3993:ex:words:3:note":"あと","grammar:3993:ex:words:3:pos":"noun","grammar:3993:ex:words:4:zh":"ground","grammar:3993:ex:words:4:note":"じめん","grammar:3993:ex:words:4:pos":"noun","grammar:3993:ex:words:5:zh":"(nominative)","grammar:3993:ex:words:5:pos":"particle","grammar:3993:ex:words:6:zh":"dried","grammar:3993:ex:words:6:note":"かわいた","grammar:3993:ex:words:6:pos":"verb","grammar:3993:ex:points:0":"❗乾く (かわく): (for an object) to dry (intransitive verb); vs 渇く (to be thirsty, same pronunciation); 地面が乾く = the ground dries.","grammar:3993:ex:points:1":"地面が乾く: the ground dries.","grammar:3993:ex2:trans":"Hair dries right away.","grammar:3993:ex2:structure":"〜がすぐに乾く","grammar:3993:ex2:words:0:zh":"hair","grammar:3993:ex2:words:0:note":"かみのけ","grammar:3993:ex2:words:0:pos":"noun","grammar:3993:ex2:words:1:zh":"(nominative)","grammar:3993:ex2:words:1:pos":"particle","grammar:3993:ex2:words:2:zh":"soon","grammar:3993:ex2:words:2:pos":"adverb","grammar:3993:ex2:words:3:zh":"to dry","grammar:3993:ex2:words:3:note":"かわく","grammar:3993:ex2:words:3:pos":"verb","grammar:3993:ex2:points:0":"❗髪が乾く: hair dries (乾く is intransitive).","grammar:3993:ex2:points:1":"髪が乾く: hair dries.","grammar:3993:ex3:trans":"This piece of clothing takes time to dry.","grammar:3993:ex3:structure":"〜が乾くのに時間がかかる","grammar:3993:ex3:words:0:zh":"this","grammar:3993:ex3:words:0:pos":"pre-noun adjectival","grammar:3993:ex3:words:1:zh":"clothes","grammar:3993:ex3:words:1:note":"いふく","grammar:3993:ex3:words:1:pos":"noun","grammar:3993:ex3:words:2:zh":"(topic)","grammar:3993:ex3:words:2:pos":"particle","grammar:3993:ex3:words:3:zh":"to dry","grammar:3993:ex3:words:3:note":"かわく","grammar:3993:ex3:words:3:pos":"verb","grammar:3993:ex3:words:4:zh":"(nominalizer)","grammar:3993:ex3:words:4:pos":"particle","grammar:3993:ex3:words:5:zh":"(what took the time)","grammar:3993:ex3:words:5:pos":"particle","grammar:3993:ex3:words:6:zh":"time","grammar:3993:ex3:words:6:note":"じかん","grammar:3993:ex3:words:6:pos":"noun","grammar:3993:ex3:words:7:zh":"(nominative)","grammar:3993:ex3:words:7:pos":"particle","grammar:3993:ex3:words:8:zh":"to take (time)","grammar:3993:ex3:words:8:pos":"verb","grammar:3993:ex3:points:0":"❗〜のに時間がかかる: it takes time to…; 服が乾く = the clothes dry.","grammar:3993:ex3:points:1":"乾くのに時間がかかる: takes a long time to dry.","grammar:3993:ex4:trans":"The wet ground dries quickly because of the wind.","grammar:3993:ex4:structure":"〜で〜が早く乾く","grammar:3993:ex4:words:0:zh":"wind","grammar:3993:ex4:words:0:note":"かぜ","grammar:3993:ex4:words:0:pos":"noun","grammar:3993:ex4:words:1:zh":"(cause)","grammar:3993:ex4:words:1:pos":"particle","grammar:3993:ex4:words:2:zh":"wet","grammar:3993:ex4:words:2:note":"ぬれた","grammar:3993:ex4:words:2:pos":"verb","grammar:3993:ex4:words:3:zh":"ground","grammar:3993:ex4:words:3:note":"じめん","grammar:3993:ex4:words:3:pos":"noun","grammar:3993:ex4:words:4:zh":"(nominative)","grammar:3993:ex4:words:4:pos":"particle","grammar:3993:ex4:words:5:zh":"quickly","grammar:3993:ex4:words:5:note":"はやく","grammar:3993:ex4:words:5:pos":"adjective","grammar:3993:ex4:words:6:zh":"to dry","grammar:3993:ex4:words:6:note":"かわく","grammar:3993:ex4:words:6:pos":"verb","grammar:3993:ex4:points:0":"❗〜で乾く: to dry because of… (で marks cause); 濡れた地面 = wet ground.","grammar:3993:ex4:points:1":"風で乾く: to dry in the wind.","grammar:3993:ex5:trans":"Let's wait here until the clothes dry.","grammar:3993:ex5:structure":"〜が乾くまで〜待ちましょう","grammar:3993:ex5:words:0:zh":"clothes","grammar:3993:ex5:words:0:note":"ふく","grammar:3993:ex5:words:0:pos":"noun","grammar:3993:ex5:words:1:zh":"(nominative)","grammar:3993:ex5:words:1:pos":"particle","grammar:3993:ex5:words:2:zh":"to dry","grammar:3993:ex5:words:2:note":"かわく","grammar:3993:ex5:words:2:pos":"verb","grammar:3993:ex5:words:3:zh":"until","grammar:3993:ex5:words:3:pos":"particle","grammar:3993:ex5:words:4:zh":"here","grammar:3993:ex5:words:4:pos":"pronoun","grammar:3993:ex5:words:5:zh":"(place)","grammar:3993:ex5:words:5:pos":"particle","grammar:3993:ex5:words:6:zh":"let's wait","grammar:3993:ex5:words:6:note":"まちましょう","grammar:3993:ex5:words:6:pos":"verb","grammar:3993:ex5:points:0":"❗〜まで: until…; 服が乾く = the clothes dry.","grammar:3993:ex5:points:1":"乾くまで待つ: to wait until it dries."},"3994":{"example:3994:exzh":"Please sit there.","example:3994:exzh2":"He is waiting there.","example:3994:exzh3":"That book is placed there.","example:3994:exzh4":"What are you doing there?","example:3994:exzh5":"We eat lunch there.","grammar:3994:ex:trans":"Please sit there.","grammar:3994:ex:structure":"そこ＋に＋座ってください。「〜に座る」＝sit in/on….","grammar:3994:ex:explain":"The focus is the demonstrative 「そこ」 (there), which refers to a place relatively close to the listener (written 「其処」 in kanji, though kana is normally used). 「〜に座る」 means “sit in/on…,” with 「に」 marking where someone sits. 「〜てください」 is a polite request meaning “please…,” using the te-form 「座って」. The whole sentence asks the other person to sit in that spot. The key points are the distance implied by 「そこ」 (near the listener) and the location particle 「に」 in 「〜に座る」.","grammar:3994:ex:words:0:zh":"there","grammar:3994:ex:words:0:pos":"pronoun","grammar:3994:ex:words:1:zh":"(the destination)","grammar:3994:ex:words:1:pos":"particle","grammar:3994:ex:words:2:zh":"sit","grammar:3994:ex:words:2:note":"すわって; te-form","grammar:3994:ex:words:2:pos":"verb","grammar:3994:ex:words:3:zh":"please","grammar:3994:ex:words:3:note":"〜てください","grammar:3994:ex:words:3:pos":"verb","grammar:3994:ex:points:0":"そこ: there (near the listener)","grammar:3994:ex:points:1":"〜に座る: to sit at/in …","grammar:3994:ex2:trans":"He is waiting there.","grammar:3994:ex2:structure":"〜は＋place＋で＋待っている。「で」 marks the location of an action.","grammar:3994:ex2:words:0:zh":"he","grammar:3994:ex2:words:0:note":"かれ","grammar:3994:ex2:words:0:pos":"pronoun","grammar:3994:ex2:words:1:zh":"(topic marker)","grammar:3994:ex2:words:1:pos":"particle","grammar:3994:ex2:words:2:zh":"there","grammar:3994:ex2:words:2:note":"そこ (kanji spelling)","grammar:3994:ex2:words:2:pos":"pronoun","grammar:3994:ex2:words:3:zh":"(place of the action)","grammar:3994:ex2:words:3:pos":"particle","grammar:3994:ex2:words:4:zh":"waiting","grammar:3994:ex2:words:4:note":"〜ている marks an ongoing action","grammar:3994:ex2:words:4:pos":"verb","grammar:3994:ex2:points:0":"其処（そこ）: there (kanji spelling)","grammar:3994:ex2:points:1":"で: the location where an action takes place (そこで＝there)","grammar:3994:ex3:trans":"That book has been placed there.","grammar:3994:ex3:structure":"その＋noun＋は＋place＋に＋置いてある。「〜てある」 expresses the state resulting from something having been placed somewhere intentionally.","grammar:3994:ex3:words:0:zh":"that","grammar:3994:ex3:words:0:pos":"pre-noun adjectival","grammar:3994:ex3:words:1:zh":"book","grammar:3994:ex3:words:1:note":"ほん","grammar:3994:ex3:words:1:pos":"noun","grammar:3994:ex3:words:2:zh":"(topic marker)","grammar:3994:ex3:words:2:pos":"particle","grammar:3994:ex3:words:3:zh":"there","grammar:3994:ex3:words:3:note":"そこ","grammar:3994:ex3:words:3:pos":"pronoun","grammar:3994:ex3:words:4:zh":"(the place where something exists)","grammar:3994:ex3:words:4:pos":"particle","grammar:3994:ex3:words:5:zh":"leave it","grammar:3994:ex3:words:5:note":"おいてある; 〜てある expresses the state of something having been placed somewhere","grammar:3994:ex3:words:5:pos":"verb","grammar:3994:ex3:points:0":"〜てある: someone has done… and left it that way (置いてある＝has been placed and left there)","grammar:3994:ex3:points:1":"〜に置いてある: has been placed in/on…","grammar:3994:ex4:trans":"What are you doing there?","grammar:3994:ex4:structure":"placeで＋何を＋しているの？「で」 marks the location of an action; 「の？」 is a conversational question ending.","grammar:3994:ex4:words:0:zh":"there","grammar:3994:ex4:words:0:note":"そこ","grammar:3994:ex4:words:0:pos":"pronoun","grammar:3994:ex4:words:1:zh":"(place of the action)","grammar:3994:ex4:words:1:pos":"particle","grammar:3994:ex4:words:2:zh":"what","grammar:3994:ex4:words:2:note":"なに","grammar:3994:ex4:words:2:pos":"question word","grammar:3994:ex4:words:3:zh":"(object marker)","grammar:3994:ex4:words:3:pos":"particle","grammar:3994:ex4:words:4:zh":"is doing","grammar:3994:ex4:words:4:note":"〜ている marks an ongoing action","grammar:3994:ex4:words:4:pos":"verb","grammar:3994:ex4:words:5:zh":"(question tone, casual)","grammar:3994:ex4:words:5:pos":"particle","grammar:3994:ex4:points:0":"で: the location where an action takes place (そこで)","grammar:3994:ex4:points:1":"〜の？: a conversational question ending","grammar:3994:ex5:trans":"We eat lunch there.","grammar:3994:ex5:structure":"〜は＋placeで＋nounを＋食べる。","grammar:3994:ex5:words:0:zh":"we","grammar:3994:ex5:words:0:note":"わたしたち","grammar:3994:ex5:words:0:pos":"pronoun","grammar:3994:ex5:words:1:zh":"(topic marker)","grammar:3994:ex5:words:1:pos":"particle","grammar:3994:ex5:words:2:zh":"there","grammar:3994:ex5:words:2:note":"そこ","grammar:3994:ex5:words:2:pos":"pronoun","grammar:3994:ex5:words:3:zh":"(place of the action)","grammar:3994:ex5:words:3:pos":"particle","grammar:3994:ex5:words:4:zh":"lunch","grammar:3994:ex5:words:4:note":"ちゅうしょく","grammar:3994:ex5:words:4:pos":"noun","grammar:3994:ex5:words:5:zh":"(object marker)","grammar:3994:ex5:words:5:pos":"particle","grammar:3994:ex5:words:6:zh":"eat","grammar:3994:ex5:words:6:note":"たべる","grammar:3994:ex5:words:6:pos":"verb","grammar:3994:ex5:points:0":"で: the location where an action takes place (そこで)","grammar:3994:ex5:points:1":"昼食: lunch","exam:3994:zh":"I'll wait here, so please wait right where you're standing now.","exam:3994:why":"「そこ」 can refer to where the listener is. 「ここ」 refers to where the speaker is, which doesn't match the position separately assigned to the other person in the sentence."},"3995":{"example:3995:exzh":"That car can turn quickly.","example:3995:exzh2":"We walked around the park.","example:3995:exzh3":"The ring turned on his finger.","example:3995:exzh4":"The earth goes around the sun.","example:3995:exzh5":"The hands of the clock are always turning.","grammar:3995:ex:trans":"That car can turn quickly.","grammar:3995:ex:structure":"速く回ることができる","grammar:3995:ex:explain":"The key point is the intransitive verb 「回る」, meaning to rotate, go around, or turn, as opposed to the transitive verb 「回す」 (to turn something). Here it combines with the potential pattern 「〜ことができる」 meaning to be able to…, so 「回ることができる」 means to be able to turn. The adverb 「速く」 comes from the i-adjective 「速い」 and modifies the verb to mean quickly. The topic 「車」 takes 「は」. The sentence says that car can turn quickly, and the intransitive verb plus the potential expression is the main point.","grammar:3995:ex:words:0:zh":"that","grammar:3995:ex:words:0:pos":"pre-noun adjectival","grammar:3995:ex:words:1:zh":"car","grammar:3995:ex:words:1:note":"くるま","grammar:3995:ex:words:1:pos":"noun","grammar:3995:ex:words:2:zh":"(topic)","grammar:3995:ex:words:2:pos":"particle","grammar:3995:ex:words:3:zh":"quickly","grammar:3995:ex:words:3:note":"はやく","grammar:3995:ex:words:3:pos":"adjective","grammar:3995:ex:words:4:zh":"turn","grammar:3995:ex:words:4:note":"まわる","grammar:3995:ex:words:4:pos":"verb","grammar:3995:ex:words:5:zh":"(nominalizer)","grammar:3995:ex:words:5:pos":"noun","grammar:3995:ex:words:6:zh":"(nominative)","grammar:3995:ex:words:6:pos":"particle","grammar:3995:ex:words:7:zh":"be able to","grammar:3995:ex:words:7:pos":"verb","grammar:3995:ex:points:0":"❗回る (まわる): to rotate, to go around, to make the rounds (intransitive verb); vs 回す (transitive verb, to turn something); 速く回る = to turn quickly.","grammar:3995:ex:points:1":"回る: to rotate.","grammar:3995:ex2:trans":"We walked around the park.","grammar:3995:ex2:structure":"〜を回って散歩をした","grammar:3995:ex2:words:0:zh":"we","grammar:3995:ex2:words:0:note":"わたしたち","grammar:3995:ex2:words:0:pos":"pronoun","grammar:3995:ex2:words:1:zh":"(topic)","grammar:3995:ex2:words:1:pos":"particle","grammar:3995:ex2:words:2:zh":"park","grammar:3995:ex2:words:2:note":"こうえん","grammar:3995:ex2:words:2:pos":"noun","grammar:3995:ex2:words:3:zh":"(path)","grammar:3995:ex2:words:3:pos":"particle","grammar:3995:ex2:words:4:zh":"to go around","grammar:3995:ex2:words:4:note":"まわって","grammar:3995:ex2:words:4:pos":"verb","grammar:3995:ex2:words:5:zh":"take a walk","grammar:3995:ex2:words:5:note":"さんぽを","grammar:3995:ex2:words:5:pos":"noun","grammar:3995:ex2:words:6:zh":"did","grammar:3995:ex2:words:6:pos":"verb","grammar:3995:ex2:points:0":"❗公園を回る: to walk around the park (を marks the path); 散歩をする = to take a walk.","grammar:3995:ex2:points:1":"公園を回る: to go around the park.","grammar:3995:ex3:trans":"The ring turned on his finger.","grammar:3995:ex3:structure":"〜は〜の上で回った","grammar:3995:ex3:explain":"「彼の指の上」 builds up in order to mean on top of or above his finger, and the following 「で」 marks where the turning happened. 「回った」 describes the ring itself turning; the sentence doesn't say who made it turn.","grammar:3995:ex3:words:0:zh":"that","grammar:3995:ex3:words:0:pos":"pre-noun adjectival","grammar:3995:ex3:words:1:zh":"ring; circle","grammar:3995:ex3:words:1:note":"わ","grammar:3995:ex3:words:1:pos":"noun","grammar:3995:ex3:words:2:zh":"(topic)","grammar:3995:ex3:words:2:pos":"particle","grammar:3995:ex3:words:3:zh":"he","grammar:3995:ex3:words:3:note":"かれ","grammar:3995:ex3:words:3:pos":"pronoun","grammar:3995:ex3:words:4:zh":"(possession)","grammar:3995:ex3:words:4:pos":"particle","grammar:3995:ex3:words:5:zh":"fingers","grammar:3995:ex3:words:5:note":"ゆび","grammar:3995:ex3:words:5:pos":"noun","grammar:3995:ex3:words:6:zh":"(place modifier)","grammar:3995:ex3:words:6:pos":"particle","grammar:3995:ex3:words:7:zh":"on top of","grammar:3995:ex3:words:7:note":"うえ","grammar:3995:ex3:words:7:pos":"noun","grammar:3995:ex3:words:8:zh":"(place of the action)","grammar:3995:ex3:words:8:pos":"particle","grammar:3995:ex3:words:9:zh":"to turn; to rotate","grammar:3995:ex3:words:9:note":"まわっ","grammar:3995:ex3:words:9:pos":"verb","grammar:3995:ex3:words:10:zh":"(past, completed)","grammar:3995:ex3:words:10:pos":"auxiliary verb","grammar:3995:ex3:points:0":"「〜の上で」 indicates that an action takes place on top of something.","grammar:3995:ex3:points:1":"「回る」 is an intransitive verb; to make something turn, use the transitive verb 「回す」.","grammar:3995:ex4:trans":"The Earth goes around the Sun.","grammar:3995:ex4:structure":"地球 + は + 太陽の周り + を + 回る","grammar:3995:ex4:words:0:zh":"the earth","grammar:3995:ex4:words:0:note":"chikyū; the planet we live on","grammar:3995:ex4:words:0:pos":"noun","grammar:3995:ex4:words:1:zh":"marks the topic","grammar:3995:ex4:words:1:pos":"particle","grammar:3995:ex4:words:2:zh":"sun","grammar:3995:ex4:words:2:note":"taiyō; the sun","grammar:3995:ex4:words:2:pos":"noun","grammar:3995:ex4:words:3:zh":"'s","grammar:3995:ex4:words:3:pos":"particle","grammar:3995:ex4:words:4:zh":"surroundings","grammar:3995:ex4:words:4:note":"mawari; the area around something","grammar:3995:ex4:words:4:pos":"noun","grammar:3995:ex4:words:5:zh":"the area you pass through","grammar:3995:ex4:words:5:pos":"particle","grammar:3995:ex4:words:6:zh":"to go around; to revolve","grammar:3995:ex4:words:6:note":"mawaru; to rotate or go around","grammar:3995:ex4:words:6:pos":"verb","grammar:3995:ex4:points:0":"「周りを回る」 means going around something, and is a typical pairing with 「回る」.","grammar:3995:ex4:points:1":"「太陽の周り」 joins the words with 「の」 and means the area around the sun.","grammar:3995:ex4:points:2":"Here 「を」 marks the path or area that the movement passes through.","grammar:3995:ex5:trans":"The hands of the clock are always turning.","grammar:3995:ex5:structure":"〜は常に回っている","grammar:3995:ex5:words:0:zh":"clock","grammar:3995:ex5:words:0:note":"とけい","grammar:3995:ex5:words:0:pos":"noun","grammar:3995:ex5:words:1:zh":"'s","grammar:3995:ex5:words:1:pos":"particle","grammar:3995:ex5:words:2:zh":"hand (of a clock)","grammar:3995:ex5:words:2:note":"はり","grammar:3995:ex5:words:2:pos":"noun","grammar:3995:ex5:words:3:zh":"(topic)","grammar:3995:ex5:words:3:pos":"particle","grammar:3995:ex5:words:4:zh":"always","grammar:3995:ex5:words:4:note":"つねに","grammar:3995:ex5:words:4:pos":"adverb","grammar:3995:ex5:words:5:zh":"is turning","grammar:3995:ex5:words:5:note":"まわっている","grammar:3995:ex5:words:5:pos":"verb","grammar:3995:ex5:points:0":"❗時計の針: the hands of a clock; 針が回る = the hand turns.","grammar:3995:ex5:points:1":"針が回る: the hand turns."},"3996":{"example:3996:exzh":"He decided to take a new job.","example:3996:exzh2":"A lot of experience was gained in this field.","example:3996:exzh3":"After graduating from school, you start job hunting.","example:3996:exzh4":"Her goal is to become a teacher.","example:3996:exzh5":"He has been working as a teacher ever since he graduated from university."},"3997":{"example:3997:exzh":"He works as a mercenary.","example:3997:exzh2":"Mercenaries often take part in wars.","example:3997:exzh3":"The debate about mercenaries is still going on.","example:3997:exzh4":"This novel is about mercenaries.","example:3997:exzh5":"Mercenaries often take on dangerous missions."},"3998":{"example:3998:exzh":"It's important to believe in your own choices.","example:3998:exzh2":"He is a person who is strict with himself.","example:3998:exzh3":"Sometimes you have to fight to protect yourself.","example:3998:exzh4":"Please walk your own path.","example:3998:exzh5":"It takes effort to go beyond your own limits."},"3999":{"example:3999:exzh":"His opinion contains a strong assertion.","example:3999:exzh2":"This scent is intense and unforgettable.","example:3999:exzh3":"She made a strong impression.","example:3999:exzh4":"That movie stirs up intense emotions.","example:3999:exzh5":"The intense light seems to pierce my eyes."}};